   "titolo": "Scontro tra treni a sud del Cairo: decine di vittime e oltre cento feriti",
   "orig": "Footage shows derailed carriages after fatal train crash in Egypt",
   "lead": "Un grave incidente ferroviario si è verificato a sud della capitale egiziana, dove un convoglio è deragliato in seguito alla violenta collisione con un altro convoglio in transito. Le autorità sanitarie locali hanno confermato diversi decessi e segnalato più di cento passeggeri feriti, soccorsi tempestivamente grazie all'invio sul luogo del disastro di oltre cinquanta ambulanze. Il presidente egiziano Abdel Fattah al-Sisi ha annunciato l'apertura immediata di un'inchiesta ufficiale per accertare le dinamiche del disastro, assicurando che chiunque si sia reso responsabile di negligenze o violazioni della sicurezza sarà chiamato a risponderne pienamente.",
   "more": [
    "La rete ferroviaria egiziana è una delle più antiche del Medio Oriente e trasporta quotidianamente milioni di pendolari. Negli ultimi decenni l'infrastruttura è stata segnata da gravi incidenti dovuti a problemi di manutenzione, segnalamento obsoleto e carenze gestionali. Il governo ha avviato programmi di ammodernamento tecnologico delle linee per migliorare la sicurezza complessiva dei trasporti."
   ],
