   "id": "z542315a0",
   "sez": "dibattito",
   "titolo": "Corteo 'Red Line' ad Amsterdam: centinaia di migliaia di persone chiedono lo stop alle armi verso Israele",
   "orig": "Hundreds of thousands join Amsterdam’s ‘Red Line’ protest against Israel",
   "lead": "Nelle strade di Amsterdam si è svolta una massiccia manifestazione pubblica denominata 'Red Line', alla quale hanno preso parte centinaia di migliaia di cittadini. I manifestanti si sono mobilitati per chiedere al governo olandese e all'Unione Europea l'adozione di severe restrizioni commerciali contro Israele e l'immediata sospensione di qualsiasi vendita o trasferimento di equipaggiamenti militari. Il corteo ha sfilato pacificamente attraverso la città, sostenendo che le forniture belliche e gli accordi commerciali in vigore violino i principi del diritto internazionale e la protezione delle popolazioni civili coinvolte nel conflitto in Medio Oriente. Lo riferisce Al Jazeera.",
   "more": [
    "In Europa il dibattito sull'esportazione di forniture militari verso Paesi coinvolti in conflitti armati è regolato da normative nazionali e da posizioni comuni dell'Unione Europea. Le organizzazioni non governative e i movimenti civici sostengono che la vendita di armi debba essere subordinata al rigoroso rispetto dei diritti umani, mentre le autorità nazionali e le industrie della difesa difendono la validità dei trattati di cooperazione strategica bilaterale precedentemente stipulati."
   ],
