   "id": "zc35e786a",
   "sez": "sport",
   "titolo": "Formula 1 in Brasile: Lando Norris vince la gara, settimo posto per Leclerc",
   "orig": "F1: in Brasile vince Norris, settima la Ferrari di Leclerc",
   "lead": "Lando Norris ha trionfato nel Gran Premio del Brasile di Formula 1 al termine di una gara ricca di colpi di scena sul circuito di Interlagos. Sul podio sono salite le due monoposto della Red Bull guidate da Max Verstappen e da Isack Hadjar, mentre il giovane Andrea Kimi Antonelli ha conquistato un incoraggiante quinto posto. Giornata complicata invece per la Ferrari di Charles Leclerc, che ha tagliato il traguardo in settima posizione, mentre il pluricampione Lewis Hamilton ha concluso al nono posto. Lo riferisce ANSA.",
   "more": [
    "Il tracciato brasiliano di Interlagos è storicamente noto per i suoi cambi meteorologici repentini e per le sue sezioni veloci e tecniche che mettono a dura prova la gestione dei pneumatici. Nelle fasi conclusive del mondiale ogni punto conquistato assume un peso determinante per la graduatoria piloti e per il campionato costruttori, accendendo la rivalità tra scuderie rivali."
   ],
