   "titolo": "Premier League spettacolare a Old Trafford: Manchester United e Aston Villa pareggiano 4-4",
   "orig": "Išsigelbėjęs „Man United“ aštuonių įvarčių trileryje išplėšė lygiąsias prieš „Aston Villa“",
   "lead": "Un incontro ricco di colpi di scena e reti ha infiammato il pomeriggio di Premier League a Old Trafford, dove Manchester United e Aston Villa si sono divise la posta con uno spettacolare pareggio per 4-4. Gli ospiti si sono portati avanti prima sul 2-0 e poi sul 4-2, guidati anche dal gol del proprio attaccante Nicolas Jackson, ma i padroni di casa non si sono arresi. Con una reazione d'orgoglio culminata al novantaseiesimo minuto di gioco, i Red Devils hanno evitato la sconfitta agguantando un pari insperato negli ultimi istanti.",
   "more": [
    "Il campionato inglese di Premier League è rinomato per l'intensità agonistica e l'equilibrio tra le formazioni. Le partite ricche di gol come quella dell'Old Trafford mettono in luce sia il grande potenziale offensivo delle squadre di vertice sia le ricorrenti fragilità difensive che caratterizzano le fasi più delicate della stagione calcistica britannica."
   ],
