   "id": "z409199b5",
   "sez": "mondo",
   "titolo": "Sconfitta repubblicana ai midterm USA: Trump promette di tornare più forte",
   "orig": "Trump vows comeback as bitter showdown with Congress looms",
   "lead": "All'indomani della pesante battuta d'arresto elettorale subita dal Partito Repubblicano nelle elezioni di metà mandato, Donald Trump ha assicurato ai propri sostenitori che intende tornare sulla scena politica più forte e determinato di prima. L'esito delle urne apre uno scontro aspro con il Congresso degli Stati Uniti, lasciando il presidente in una posizione di debolezza politica nei due anni conclusivi del suo mandato presidenziale. Nel frattempo l'opposizione democratica prepara le proprie contromisure parlamentari alla Camera, preannunciando iniziative per contrastare le nomine dell'amministrazione e delineando una fase di forte paralisi legislativa a Washington.",
   "more": [
    "Negli Stati Uniti le elezioni di metà mandato rinnovano tutti i seggi della Camera e un terzo del Senato, rappresentando un banco di prova fondamentale per l'amministrazione in carica. La perdita del controllo parlamentare trasforma il presidente in una cosiddetta 'anatra zoppa', limitandone drasticamente la capacità di approvare riforme e il bilancio federale."
   ],
