   "sez": "ambiente",
   "titolo": "Emergenza smog a Nuova Delhi: l'aria più inquinata del decennio alla vigilia di Diwali",
   "orig": "India: Delhi chokes on most polluted Diwali eve in 10 years",
   "lead": "La capitale indiana Nuova Delhi si è classificata come la grande metropoli più inquinata al mondo alla vigilia delle celebrazioni di Diwali, registrando i peggiori livelli di qualità dell'aria dell'ultimo decennio. Per contenere l'impatto dei fumi tossici, la Corte Suprema dell'India ha autorizzato esclusivamente l'impiego di fuochi d'artificio ecologici e a basse emissioni durante le festività. Tuttavia, i movimenti ambientalisti hanno duramente contestato il provvedimento bollandolo come una semplice operazione di facciata ecologica, avvertendo che le concentrazioni di particolato fine aumenteranno sensibilmente nei giorni successivi.",
   "more": [
    "Durante i mesi autunnali la pianura indogangetica soffre di una grave combinazione di fattori inquinanti, tra cui l'abbruciamento delle stoppie agricole nei campi circostanti, le emissioni industriali e il traffico veicolare. Il fenomeno dell'inversione termica intrappola le sostanze inquinanti a bassa quota, rendendo l'aria pericolosa per le vie respiratorie della popolazione locale."
   ],
