   "sez": "viaggi",
   "titolo": "Tokyo inaugura la stagione invernale: luminarie nel parco di Yoyogi e mercatini",
   "orig": "Tokyo Events This Week: Yoyogi Forest of Lights, Santa Parade, and Christmas Markets",
   "lead": "La capitale giapponese si prepara ad accogliere la stagione invernale con una ricca serie di iniziative all'aperto, accensioni scenografiche e mercatini natalizi. Tra le novità principali spicca l'inaugurazione del percorso luminoso nel parco di Yoyogi, che apre ufficialmente i battenti per illuminare le vie cittadine insieme a parate a tema e allestimenti festivi. L'offerta per i visitatori spazia da esposizioni artistiche e di design fino a degustazioni gastronomiche, segnando l'avvio delle attrazioni turistiche che accompagneranno residenti e viaggiatori fino alle festività di fine anno. Lo riferisce Tokyo Cheapo.",
   "more": [
    "Le illuminazioni invernali, conosciute in Giappone come 'winter illuminations', rappresentano una delle maggiori attrattive turistiche urbane da novembre a febbraio. Grandi parchi, complessi commerciali e viali alberati di metropoli come Tokyo vengono trasformati con milioni di luci a led per stimolare il commercio locale e attirare flussi costanti di visitatori internazionali."
   ],
