   "id": "z7b045c51",
   "sez": "ingegneria",
   "titolo": "Formazione IEEE per docenti: lezioni su semiconduttori e intelligenza artificiale nelle scuole",
   "orig": "IEEE Program Schools Preuniversity Educators On Tech Topics",
   "lead": "Il programma TryEngineering promosso dall'IEEE è giunto al suo terzo anno di attività con l'obiettivo di aggiornare i docenti delle scuole preuniversitarie sui settori tecnologici più innovativi. Gli incontri formativi svolti negli Stati Uniti e in una sede distaccata in Egitto hanno coinvolto decine di insegnanti, offrendo lezioni pratiche e nozioni sull'intelligenza artificiale, la tecnologia dei semiconduttori e le metodologie di progettazione ingegneristica da portare in aula. L'iniziativa punta a fornire strumenti didattici moderni per avvicinare gli studenti delle scuole secondarie agli studi scientifici e tecnologici. Lo riferisce IEEE Spectrum.",
   "more": [
    "L'insegnamento precoce delle materie STEM (scienza, tecnologia, ingegneria e matematica) è considerato fondamentale per colmare la carenza di competenze tecniche a livello globale. Coinvolgere direttamente gli insegnanti attraverso laboratori dedicati ai semiconduttori e all'informatica avanzata consente di rinnovare i programmi scolastici tradizionali, stimolando la capacità di problem solving nei giovani."
   ],
