   "id": "zd937efc5",
   "sez": "musica",
   "titolo": "Rosalía festeggia un anno dell'album 'Lux' con una raccolta di mille brani e un cofanetto",
   "orig": "Rosalía Celebrates Lux Anniversary with 1,000-Song Playlist",
   "lead": "L'artista spagnola Rosalía ha deciso di celebrare il primo anniversario del suo acclamato quarto album 'Lux' pubblicando una speciale playlist composta da mille brani musicali e lanciando un cofanetto celebrativo per i collezionisti. La vasta selezione audio spazia tra generi ed epoche profondamente eterogenei, includendo composizioni di Mozart accanto a tracce di Yung Lean, Labi Siffre e Pink Floyd. Riflettendo sulla creazione del disco, la cantante ha spiegato di essersi ispirata all'architettura delle cattedrali, concepite come spazi monumentali capaci di unire misticismo sonoro, tradizione corale e ricerca sonora d'avanguardia.",
   "more": [
    "Rosalía è considerata una delle figure più innovative del pop globale contemporaneo grazie alla sua capacità di fondere il flamenco tradizionale con ritmi urbani, reggaeton ed elettronica sperimentale. L'impiego di influenze della musica classica ed eclettiche selezioni d'ascolto testimoniano la complessità del suo percorso compositivo e visivo."
   ],
