   "id": "z9fc09510",
   "sez": "adolescenti",
   "titolo": "Bocciatura in terza media con voto insufficiente: il TAR conferma la decisione dei docenti",
   "orig": "Voti da 4 a 5 in cinque materie e 6 in condotta, la famiglia ricorre, ma i giudici confermano la bocciatura dell’alunna: “Valutazione dei docenti è stata corretta”",
   "lead": "Il Tribunale Amministrativo Regionale della Lombardia ha respinto il ricorso presentato dai genitori di una studentessa di scuola secondaria di primo grado, confermando la legittimità della sua mancata ammissione all'esame conclusivo di terza media. La ragazza aveva riportato voti compresi tra il 4 e il 5 in cinque diverse discipline scolastiche e una valutazione di 6 in condotta nell'anno scolastico 2025-2026. Con la sentenza numero 1378, i giudici amministrativi di Brescia hanno stabilito che il giudizio espresso dal consiglio di classe è stato pienamente corretto e privo di vizi procedurali. Lo riferisce Orizzonte Scuola.",
   "more": [
    "La valutazione finale degli studenti nelle scuole secondarie di primo grado è rimessa alla discrezionalità tecnica del consiglio di classe, organo collegiale che valuta non solo il profitto ma anche la maturazione globale e l'impegno. I giudici amministrativi possono annullare tali provvedimenti solo in presenza di palesi errori formali o palesi violazioni di legge."
   ],
