   "id": "zd7305689",
   "sez": "spazio",
   "titolo": "Meteo spaziale: come le aurore polari possono minacciare le reti elettriche terrestri",
   "orig": "How space weather powers auroras in the sky and threatens power grids on the ground",
   "lead": "Uno studio approfondito evidenzia il legame diretto tra i fenomeni del meteo spaziale che generano le splendide aurore e i rischi concreti per le infrastrutture tecnologiche sulla Terra. Sebbene le aurore boreali appaiano come drappeggi luminosi colorati e remoti nel cielo notturno, esse sono innescate dall'interazione tra particelle solari cariche e la magnetosfera terrestre. Questa intensa attività geomagnetica può indurre forti correnti elettriche nel terreno capaci di sovraccaricare e danneggiare trasformatori ad alta tensione e intere reti di distribuzione elettrica superficiali. Lo riferisce Phys.org – Spazio.",
   "more": [
    "Le tempeste geomagnetiche hanno origine da eruzioni solari ed espulsioni di massa coronale che scagliano nello spazio nubi di plasma ionizzato. Quando queste particelle colpiscono il campo magnetico della Terra creano correnti indotte nel suolo, esponendo a rischi tecnologici non solo i satelliti in orbita ma anche gasdotti e centrali elettriche."
   ],
