   "titolo": "Sentenza dell'Aia sui vertici UÇK: la piattaforma 'Liria ka Emër' prepara petizione e sciopero",
   "orig": "“Liria ka Emër” planifikon peticion dhe grevë për vendimin e Hagës ndaj ish-krerëve të UÇK-së",
   "lead": "In Albania e Kosovo si accende il dibattito pubblico sul giudizio espresso dal tribunale speciale dell'Aia nei confronti degli ex comandanti dell'Esercito di Liberazione del Kosovo (UÇK). Il rappresentante della piattaforma civica 'Liria ka Emër', Ismail Tasholli, ha reso noto che l'organizzazione sta pianificando una raccolta firme tramite petizione e lo svolgimento di uno sciopero per protestare contro le condanne inflitte ai leader storici del movimento. I promotori hanno inviato lettere formali ai parlamentari europei e ai funzionari dell'Unione Europea per sollecitare un riesame del procedimento giudiziario, sostenendo che la sentenza travisi il valore della resistenza armata. Lo riferisce Euronews Albania.",
