   "titolo": "Ghana: l'opposizione presenta ricevute su un presunto traffico di passaporti diplomatici",
   "orig": "Minority presents bank, mobile money records in alleged diplomatic passport-selling scheme",
   "lead": "La minoranza parlamentare in Ghana afferma di essere entrata in possesso di ricevute di depositi bancari e registri di transazioni tramite denaro mobile. Secondo i parlamentari dell'opposizione, questa documentazione attesterebbe pagamenti indirizzati a un intermediario coinvolto nella vendita non autorizzata di passaporti diplomatici e di servizio ghanesi. Parallelamente, nel quadro dei pagamenti digitali nella regione dell'Africa occidentale, la Banca centrale degli Stati dell'Africa occidentale ha recentemente alzato i massimali per le transazioni di moneta elettronica, inasprendo al contempo le verifiche.",
   "more": [
    "L'uso dei circuiti di pagamento via telefono cellulare è estremamente diffuso in tutta l'Africa subsahariana, dove costituisce spesso il principale strumento di trasferimento economico. La tracciabilità informatica di questi movimenti consente sempre più di ricostruire flussi finanziari, diventando centrale sia nelle indagini giudiziarie sia nelle controversie politiche legate a episodi di corruzione."
   ],
