   "sez": "mondo",
   "titolo": "Stati Uniti: i Democratici legano crisi climatica e caro vita nella strategia elettorale",
   "orig": "How Democrats used the midterms to turn affordability concerns into ‘green populism’",
   "lead": "Nel dibattito politico statunitense seguito alle ultime tornate elettorali, i Democratici hanno collegato le preoccupazioni dei cittadini per il costo della vita alle politiche energetiche e ambientali. La strategia, definita dagli osservatori come un nuovo approccio di stampo popolare, ha unito l'aumento delle bollette e l'impatto dei grandi centri di elaborazione dati ai temi dell'emergenza climatica. Gli analisti segnalano che la vittoria in diverse gare per la Camera, il Senato e i governatorati è maturata intercettando le ansie sul potere d'acquisto, mentre i mercati attendono i dati sull'inflazione.",
   "more": [
    "Negli Stati Uniti, la pressione dell'inflazione e i rincari delle tariffe elettriche pesano sui bilanci familiari. La crescente richiesta di energia da parte dei centri di calcolo dedicati all'intelligenza artificiale aggrava i carichi di rete, spingendo le forze politiche a confrontarsi direttamente sul rapporto tra transizione ecologica e tutela economica delle famiglie."
   ],
