   "titolo": "Ex Ilva: scade il termine per le offerte vincolanti e Flacks decide di sfilarsi",
   "orig": "Ex Ilva: scade il termine per le offerte, Flacks si sfila",
   "lead": "Si è chiuso il termine per la presentazione delle offerte destinate all'acquisizione dell'ex gruppo siderurgico Ilva, con il fondo Flacks che ha scelto di fare un passo indietro. Secondo quanto riferito da fonti vicine alla società finanziaria, il gruppo si è detto disposto ad aggiornare ed eventualmente rilanciare la propria proposta solo dopo un confronto diretto con la presidente del Consiglio Giorgia Meloni. La trattativa per il polo industriale tarantino rimane dunque complessa e legata alle garanzie industriali e finanziarie richieste dal governo. Lo riferisce ANSA.",
   "more": [
    "L'ex Ilva di Taranto rappresenta il più grande impianto siderurgico d'Europa, essenziale per la produzione di acciaio ma al centro da anni di gravi crisi finanziarie, giudiziarie e ambientali. La sua gestione commissariale cerca investitori privati per garantire la continuità produttiva, l'occupazione e la necessaria transizione ecologica degli altiforni."
   ],
