   "id": "ze4214391",
   "sez": "ambiente",
   "titolo": "Germania: cani addestrati fiutano le piante invasive per proteggere la biodiversità",
   "orig": "Dogs Can Sniff-Out Invasive Plant Species With High Accuracy to Curb Their Destruction",
   "lead": "In Germania i cani da fiuto vengono impiegati con successo per individuare specie vegetali invasive aliene, che rappresentano una delle minacce più serie alla biodiversità globale. Ricercatori di Lipsia hanno condotto una sperimentazione per valutare l'efficacia di conduttori volontari affiancati dai loro animali, rilevando che le unità cinofile sono capaci di localizzare la vegetazione infestante in natura con un'accuratezza del settantacinque per cento. Questa tecnica innovativa permette di intervenire tempestivamente nelle aree boschive e agricole prima che la proliferazione diventi incontrollabile e distrugga gli habitat autoctoni. Lo riferisce Good News Network.",
   "more": [
    "Le piante alloctone invasive competono con le specie autoctone per l'accesso a luce, acqua e nutrienti, provocando spesso la scomparsa della flora locale e modificando interi ecosistemi. Il rilevamento precoce sul campo risulta fondamentale per sradicarle prima che producano semi, limitando i costi e i danni ecologici."
   ],
