   "sez": "spazio",
   "titolo": "Marte: rilevata una faglia attiva sotto il canyon Valles Marineris",
   "orig": "Il canyon più grande del Sistema Solare fa tremare Marte: scoperta faglia attiva sotto Valles Marineris",
   "lead": "Un evento sismico registrato dalla sonda InSight della NASA ha dimostrato che alcune faglie situate sotto Valles Marineris sono ancora in grado di muoversi ai giorni nostri. Il canyon, considerato il più imponente del Sistema Solare con i suoi circa 3.900 chilometri di estensione e 600 di larghezza, testimonia una dinamica interna non del tutto spenta. La rilevazione di questa attività tellurica apre scenari inediti per comprendere l'evoluzione geologica del pianeta rosso e chiarisce aspetti finora ignoti sulla stabilità della sua crosta nel passato e nel presente. Lo riferisce Geopop.",
   "more": [
    "La missione InSight della NASA ha operato su Marte dotata di un sismometro ad altissima sensibilità per misurare i cosiddetti terremoti marziani. Lo studio di queste onde sismiche permette agli scienziati di mappare la struttura interna del pianeta, determinando lo spessore della crosta, la natura del mantello e lo stato del nucleo."
   ],
