   "sez": "dibattito",
   "titolo": "Albania: a Tirana proseguono le proteste di studenti e cittadini contro il governo",
   "orig": "Vijon protesta në kryeqytet, protestuesit mblidhen para Kryeministrisë! Situata e qetë",
   "lead": "A Tirana centinaia di studenti, giovani e comuni cittadini si sono radunati domenica sera davanti alla sede del Consiglio dei ministri per una nuova manifestazione quotidiana contro l'esecutivo. I partecipanti continuano a chiedere a gran voce le dimissioni del governo guidato dal primo ministro, protestando contro la situazione politica generale, le difficoltà economiche e chiedendo un cambio di rotta nella gestione del Paese. La manifestazione è cominciata intorno alle 18:30 e si è svolta in un clima di calma, senza le tensioni registrate nelle giornate precedenti. Lo riferisce Euronews Albania.",
   "more": [
    "L'Albania affronta da tempo un vivace confronto democratico tra forze governative e opposizione, caratterizzato da frequenti mobilitazioni di piazza organizzate da collettivi studenteschi e società civile. I manifestanti sollecitano riforme istituzionali profonde, trasparenza amministrativa e misure efficaci contro la corruzione per favorire l'integrazione del Paese nell'Unione Europea."
   ],
