   "sez": "mondo",
   "titolo": "Mosca: inaugurata una targa per Markus Wolf, ex capo dello spionaggio est-tedesco",
   "orig": "Un fost șef al STASI, omagiat la Moscova. Cine a fost „omul fără chip” care a provocat căderea cancelarului Willy Brandt",
   "lead": "A Mosca è stata svelata una targa commemorativa in memoria di Markus Wolf, storico capo dei servizi segreti della Germania orientale. Wolf fu a lungo una figura leggendaria della Guerra fredda, noto come 'l'uomo senza volto' e celebre per l'infiltrazione di spie che determinò nel 1974 le dimissioni del cancelliere della Germania Ovest Willy Brandt. L'omaggio, composto da un bassorilievo in bronzo e da una lastra di granito, è stato collocato sulla facciata di un palazzo nel centro della capitale russa, celebrando ufficialmente il ruolo svolto dal dirigente della Stasi. Lo riferisce HotNews.",
   "more": [
    "Markus Wolf ha guidato per oltre trent'anni il dipartimento d'intelligence estera della Stasi, piazzando numerosi agenti all'interno delle massime istituzioni della Repubblica Federale Tedesca. La vicenda più nota fu il caso di Günter Guillaume, stretto collaboratore del cancelliere Brandt, il cui arresto nel 1974 provocò una storica crisi istituzionale a Bonn."
   ],
