   "sez": "adolescenti",
   "titolo": "Scuola e disabilità: i sindacati chiedono organici ATA legati ai bisogni degli alunni",
   "orig": "Personale ATA e alunni con disabilità grave, ANIEF chiede organici legati ai bisogni assistenziali e più spazio al nuovo operatore scolastico",
   "lead": "Nel dibattito sulla gestione dell'inclusione scolastica, il sindacato ANIEF ha avanzato la richiesta di rimodulare gli organici del personale amministrativo, tecnico e ausiliario (ATA) parametrando le assunzioni alle reali esigenze degli alunni con disabilità grave. Durante un confronto pubblico sui canali specializzati, i rappresentanti sindacali hanno sollecitato un ampliamento degli spazi operativi per la nuova figura professionale dell'operatore scolastico. La proposta intende rispondere in modo strutturato all'aumento delle necessità assistenziali all'interno degli istituti, garantendo una presa in carico adeguata di studentesse e studenti fragili. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Nelle scuole italiane l'assistenza agli alunni con disabilità coinvolge sia i docenti di sostegno sia i collaboratori scolastici per le esigenze igieniche e di mobilità. L'introduzione formale dell'operatore scolastico punta a creare una figura contrattuale specifica con compiti di supporto all'autonomia e all'inclusione."
   ],
