   "sez": "salute",
   "titolo": "Oncologia: un consorzio di batteri benefici previene le infezioni nei trapianti",
   "orig": "Microbiome therapy shows promise for preventing deadly bloodstream infections in early trial",
   "lead": "Uno studio clinico condotto dai ricercatori del centro City of Hope in collaborazione con altri istituti ha mostrato risultati promettenti nell'uso della terapia del microbioma per prevenire infezioni ematiche letali. Il trattamento sperimentale è stato sviluppato per i pazienti affetti da tumori del sangue sottoposti a trapianto di cellule staminali da donatore, soggetti particolarmente vulnerabili. La procedura prevede la somministrazione di sedici specie batteriche accuratamente selezionate per ricostruire la flora intestinale danneggiata, contrastando direttamente l'insorgenza di agenti patogeni pericolosi e riducendo il rischio di complicazioni gravi. Lo riferisce Medical Xpress.",
   "more": [
    "I pazienti che ricevono trapianti di midollo osseo o di cellule staminali subiscono chemioterapie aggressive che azzerano temporaneamente le difese immunitarie e alterano profondamente il microbiota intestinale. Questa compromissione apre la strada a batteri resistenti capaci di entrare nel flusso sanguigno causando sepsi gravissime."
   ],
