   "titolo": "Francia: sindacati e movimenti di piazza preparano una nuova settimana di scioperi",
   "orig": "«Conférence sociale», grève dans l’éducation, gilets jaunes… Qu’attendre de cette nouvelle semaine de mobilisation ?",
   "lead": "In Francia si apre una settimana di intensa mobilitazione sociale con scioperi previsti nel settore della scuola, appelli di protesta dei gilet gialli e l'avvio della conferenza sociale. I sindacati dei lavoratori chiedono adeguamenti salariali per far fronte all'aumento del costo della vita e maggiori risorse per i servizi pubblici, contestando le scelte di spesa del governo. Dal canto suo, l'esecutivo sostiene la necessità di mantenere il rigore finanziario proponendo il dialogo tripartito con le parti datoriali. Le agitazioni arrivano al culmine di mesi di forti frizioni sulla giustizia sociale. Lo riferisce Libération.",
   "more": [
    "La Francia conosce cicliche ondate di protesta collettiva guidate dalle confederazioni sindacali e da movimenti civici spontanei. Il confronto verte abitualmente sulla perdita di potere d'acquisto, sui contratti collettivi e sulla difesa della sanità e della scuola statale contro i tagli al bilancio pubblico varati dalle autorità."
   ],
