   "titolo": "Sudafrica: blitz e denunce svelano lo sfruttamento del lavoro nel settore tessile",
   "orig": "Threadbare: Rags and riches — how SA retail giants profit off sweatshops",
   "lead": "Documenti giudiziari e controlli governativi hanno svelato condizioni lavorative critiche nei laboratori tessili del Sudafrica, evidenziando il forte ricorso a pratiche di sfruttamento da parte delle grandi catene distributive della moda. Sebbene l'attenzione globale sia spesso focalizzata sulle fabbriche del sud-est asiatico, l'inchiesta documenta che anche la produzione locale fa registrare abusi contrattuali e paghe minime non rispettate. I dettagli emersi dalle ispezioni confermano come importanti marchi nazionali traggano profitto da stabilimenti con standard occupazionali gravemente insufficienti. Lo riferisce Daily Maverick.",
   "more": [
    "Il settore manifatturiero dell'abbigliamento in Sudafrica ha subito una forte pressione competitiva a causa delle importazioni a basso costo. Ciò ha spinto parte della filiera locale nell'economia sommersa, dove laboratori non registrati eludono la legislazione nazionale sul salario minimo e le tutele di sicurezza sul lavoro."
   ],
