   "id": "z7abc5027",
   "sez": "adolescenti",
   "titolo": "Smartphone e giovani: le indicazioni pedagogiche per l'uso consapevole di WhatsApp",
   "orig": "“Posso avere WhatsApp?”, non è un social come un altro. Le differenze e il monitoraggio delle chat: i consigli di Alberto Pellai",
   "lead": "L'arrivo del primo smartphone e l'ingresso nelle chat scolastiche rappresentano un passaggio delicato per le famiglie, sollevando frequenti dubbi tra i genitori sulla concessione dell'app WhatsApp. Lo psicoterapeuta dell'età evolutiva Alberto Pellai ha illustrato che l'applicazione di messaggistica istantanea presenta dinamiche differenti rispetto ai comuni social network, non basandosi su logiche di gradimento pubblico o algoritmi di raccomandazione. L'esperto raccomanda perciò ai genitori percorsi di monitoraggio graduale e dialogo continuo, per insegnare ai ragazzi a gestire le conversazioni di gruppo in modo sicuro e responsabile. Lo riferisce Orizzonte Scuola.",
   "more": [
    "La diffusione della messaggistica mobile tra i preadolescenti ha anticipato l'accesso alla comunicazione virtuale. Gli psicologi suggeriscono regole concordate, come l'esclusione degli schermi durante la notte e l'attenzione al linguaggio usato nei gruppi classe, per prevenire fenomeni di isolamento o cyberbullismo."
   ],
