   "id": "z7dcc6beb",
   "sez": "salute",
   "titolo": "Artrosi al ginocchio: il farmaco retatrutide riduce il dolore e favorisce il dimagrimento",
   "orig": "Experimental weight-loss drug eases painful knee osteoarthritis in two clinical trials",
   "lead": "Due studi clinici di fase tre condotti dalla Northwestern University su oltre mille partecipanti hanno dimostrato che il farmaco sperimentale iniettabile retatrutide attenua significativamente il dolore da artrosi al ginocchio. La patologia rende difficoltose azioni quotidiane come camminare, alzarsi da una sedia o salire le scale, in particolare nelle persone con problemi di forte sovrappeso. I pazienti trattati con il dosaggio più elevato del farmaco hanno registrato in media una riduzione del peso corporeo pari a circa un quarto del totale, con un miglioramento netto delle condizioni articolari. Lo riferisce Medical Xpress.",
   "more": [
    "L'osteoartrite al ginocchio è un'infiammazione cronica degenerativa della cartilagine che provoca attrito tra i capi ossei e dolore acuto. Nei pazienti obesi il carico meccanico accelera la degenerazione; la combinazione tra calo ponderale massiccio e azione farmacologica riduce sia le sollecitazioni articolari sia i mediatori dell'infiammazione."
   ],
