   "id": "zbbecf1dc",
   "sez": "dibattito",
   "titolo": "Francia: il dibattito europeo sulla crisi istituzionale e le tensioni sociali",
   "orig": "Frankreich und die Proteste: Eine Nation in der Sackgasse",
   "lead": "Le ricorrenti mobilitazioni in Francia alimentano il dibattito politico europeo sullo stato di salute della seconda economia dell'Unione. Gli analisti descrivono un Paese bloccato da crescenti difficoltà economiche, infrastrutturali e politiche maturate nel corso di decenni. Da una parte, i sindacati e i movimenti popolari sostengono che le riforme varate negli ultimi anni abbiano indebolito la protezione sociale e la qualità della vita; dall'altra, i vertici governativi e gli economisti liberali replicano che gli interventi di modernizzazione e risanamento fiscale siano indispensabili per garantire la competitività economica dello Stato. Lo riferisce Der Standard.",
   "more": [
    "La Francia affronta un elevato debito pubblico e vincoli di bilancio comunitari stringenti, mentre ampie fasce di popolazione chiedono salari più alti e la salvaguardia dello stato sociale. Tale scontro riflette la difficoltà strutturale di conciliare riforme economiche e consenso popolare in un sistema istituzionale fortemente accentrato."
   ],
