   "id": "zd11c593b",
   "sez": "ambiente",
   "titolo": "L'Uzbekistan aumenta la produzione di energia solare del 537,5% nel 2024",
   "orig": "Uzbekistan increases solar electricity output by 537.5% in 2024, Eni says",
   "lead": "Nel corso del 2024, l'Uzbekistan ha registrato una crescita del 537,5% nella produzione di energia elettrica da fonte solare rispetto al periodo precedente. L'incremento evidenzia l'accelerazione della transizione energetica nel Paese dell'Asia centrale, impegnato nello sviluppo delle fonti rinnovabili per diversificare il proprio mix energetico e soddisfare la crescente domanda interna di elettricità. I dati riflettono gli sforzi di ammodernamento delle infrastrutture energetiche nazionali condotti con il supporto di partner internazionali. Lo riferisce Trend.",
   "more": [
    "L'Uzbekistan sta investendo in modo significativo nel settore delle energie rinnovabili, con una particolare attenzione agli impianti fotovoltaici ed eolici. Sfruttando l'elevato irraggiamento solare del proprio territorio pianeggiante, il Paese punta a ridurre progressivamente la dipendenza dai combustibili fossili tradizionali e a raggiungere gli obiettivi di decarbonizzazione previsti per i prossimi decenni."
   ],
