   "titolo": "Carenza di carburante e rincari in Sudan: colture danneggiate e scioperi dei panifici",
   "orig": "Sudan fuel shortages damage crops in El Gezira as food prices soar, bakeries strike in North Kordofan",
   "lead": "In Sudan la grave carenza di carburante e l'aumento dei costi di produzione stanno causando ingenti danni alle colture agricole nello Stato di El Gezira, provocando un forte incremento dei prezzi degli alimenti. Parallelamente, nello Stato del Kordofan Settentrionale, i panifici hanno indetto uno sciopero per protestare contro l'insostenibilità dei costi di gestione e l'incapacità di rifornirsi delle materie prime necessarie per la panificazione. La crisi energetica ed alimentare sta mettendo a dura prova la popolazione locale in diverse regioni del Paese. Lo riferisce Dabanga.",
   "more": [
    "Il Sudan attraversa una profonda crisi socio-economica e infrastrutturale esacerbata dal conflitto civile, che ha compromesso le catene di approvvigionamento e la produzione agricola nazionale. L'inflazione elevata e l'indisponibilità di carburante limitano la capacità dei coltivatori di irrigare i campi e dei panifici di distribuire i beni di prima necessità."
   ],
