   "orig": "Pipoca de pão de queijo e pato com molho de refrigerante mostram criatividade de chefs em festival da Folha",
   "lead": "Nel corso del primo fine settimana del Folha Gourmet Festival, svoltosi presso il parco Villa-Lobos nella zona ovest di San Paolo, diversi chef hanno presentato preparazioni culinarie insolite che hanno attirato l'attenzione del pubblico. Tra le creazioni proposte figurano i popcorn di pane al formaggio e l'anatra accompagnata da una salsa all'arancia a base di bevande gassate. L'evento gastronomico offre ai visitatori l'opportunità di assaggiare combinazioni innovative e piatti stravaganti ideati dai professionisti della ristorazione brasiliana. Lo riferisce Folha de S.Paulo.",
