   "titolo": "Il film \"Narciso\" di Marcelo Martinessi vince il premio principale al festival di Santiago",
   "orig": "“Narciso” se lleva el principal galardón del Santiago Festival Internacional de Cine",
   "lead": "Il lungometraggi intitolato \"Narciso\", diretto dal regista Marcelo Martinessi, si è aggiudicato il riconoscimento più prestigioso al Festival Internazionale del Cinema di Santiago del Cile. L'opera cinematografica ha conquistato la giuria della rassegna cilena grazie alla sua forza espressiva e alla qualità stilistica della narrazione. Il premio consacra il nuovo progetto del cineasta paraguaiano nell'ambito del panorama cinematografico sudamericano, confermando l'attenzione della critica internazionale per le produzioni indipendenti della regione. Lo riferisce ABC Color.",
