    "Il Festival Internazionale del Cinema di Santiago rappresenta una delle principali vetrine cinematografiche dell'America Latina, ideata per promuovere sia gli autori emergenti sia i registi affermati del continente. Marcelo Martinessi è uno dei cineasti paraguaiani più riconosciuti a livello internazionale."
