   "id": "z8ac4e8f4",
   "sez": "mondo",
   "titolo": "Israele estende le misure di controllo politico ai cittadini arabi interni",
   "orig": "From 'ballot terror' to journalists' arrests: Israel warns Arabs it's watching",
   "lead": "Un'analisi sulle politiche di sicurezza in Israele segnala come le strategie di controllo tradizionalmente applicate in Cisgiordania vengano sempre più utilizzate nei confronti dei cittadini arabi israeliani. Tra i fenomeni evidenziati figurano l'arresto di giornalisti, le restrizioni alle attività politiche e le accuse di irregolarità elettorali. La tendenza riflette un inasprimento dell'azione istituzionale volta a reprimere il dissenso politico e la partecipazione pubblica delle minoranze all'interno dei confini nazionali, sollevando preoccupazioni per la tutela delle libertà civili e dell'informazione. Lo riferisce Haaretz.",
   "more": [
    "La popolazione araba israeliana rappresenta circa il venti per cento dei cittadini di Israele. I diritti politici di questa minoranza e le tensioni legate alla sicurezza nazionale costituiscono da decenni un tema di forte dibattito interno, ulteriormente accentuato dalle dinamiche del conflitto mediorientale."
   ],
