   "sez": "ambiente",
   "titolo": "Israele propone una tassa sul carbonio sui voli a lungo raggio",
   "orig": "Israel proposes carbon tax that could add $86 to the cost of long-haul flights",
   "lead": "L'Autorità Fiscale d'Israele ha avanzato la proposta di introdurre una tassa sulle emissioni di carbonio applicabile ai viaggi aerei, che potrebbe incrementare fino a ottantasei dollari il costo dei biglietti per i voli a lungo raggio. Secondo le stime ufficiali, il prelievo genererebbe un gettito annuale di circa 1,1 miliardi di shekel, pari a trecentocinquanta milioni di dollari, aumentando il prezzo dei tagliandi del quattro o cinque per cento. La maggior parte dell'onere fiscale ricadrebbe sulle fasce di reddito più elevate e sui residenti esteri. Lo riferisce Haaretz.",
   "more": [
    "La tassazione del carbonio sul trasporto aereo rientra nelle strategie internazionali per ridurre l'impronta ecologica dell'aviazione civile. Le entrate generate da tali imposte vengono di norma destinate a finanziare la transizione ecologica o a compensare i costi ambientali derivanti dai consumi energetici elevati."
   ],
