   "titolo": "Aumento dei prezzi degli ortaggi in Marocco: il pomodoro raggiunge i 17 dirham al chilo",
   "orig": "Tomato prices reach 17 MAD as vegetable costs squeeze Moroccan households",
   "lead": "In Marocco il continuo rincaro dei generi alimentari sta gravando in modo pesante sul bilancio delle famiglie, con i prezzi dei pomodori che in alcuni mercati locali hanno toccato i diciassette dirham al chilo. Durante i controlli al mercato domenicale di Tinghir, i listini hanno evidenziato valori compresi tra tredici e quindici dirham al chilogrammo, mentre all'esterno delle fiere settimanali le cifre sono scattate ulteriormente verso l'alto. L'incremento generalizzato del costo degli ortaggi suscita forte preoccupazione tra i consumatori e gli operatori del settore. Lo riferisce Hespress English.",
   "more": [
    "L'agricoltura marocchina risente frequentemente di periodi di prolungata siccità e del contestuale aumento dei costi dei fertilizzanti e dell'energia. Tali fattori condizionano la produzione orticola locale e spingono al rialzo i listini dei prodotti freschi nei mercati alimentari di tutto il Paese."
   ],
