   "titolo": "Takaful International registra un utile di 1,4 milioni di dinari nei primi nove mesi",
   "orig": "Takaful International Reports BHD 1.4 millions in Profit for the first nine months",
   "lead": "La compagnia assicurativa Takaful International ha chiuso i primi nove mesi dell'esercizio finanziario con un utile netto pari a 1,4 milioni di dinari del Bahrein, evidenziando una crescita del trenta per cento rispetto allo stesso periodo dell'anno precedente. I risultati positivi confermano la solida redditività della società e l'espansione delle sue attività operative nel settore finanziario islamico. La dirigenza ha espresso soddisfazione per le prestazioni commerciali registrate, che testimoniano l'efficacia delle strategie aziendali adottate sul mercato regionale. Lo riferisce Daily Tribune (Bahrein).",
   "more": [
    "Il Takaful è un sistema assicurativo conforme ai principi della finanza islamica, basato sulla cooperazione reciproca e sulla condivisione del rischio tra i partecipanti. Il settore delle assicurazioni islamiche è in forte espansione nei Paesi del Golfo Persico grazie alla domanda di strumenti finanziari etici."
   ],
