   "sez": "economia",
   "titolo": "L'integrazione dei sistemi di pagamento istantaneo aumenta del 4% il commercio bilaterale",
   "orig": "Integração de sistemas como o Pix aumenta em 4% comércio bilateral, diz Banco Central europeu",
   "lead": "Secondo uno studio diffuso dalla Banca Centrale Europea, i Paesi che collegano direttamente i rispettivi sistemi di pagamento digitale e istantaneo, simili al modello brasiliano Pix, registrano un incremento medio del quattro per cento nel commercio bilaterale. L'interconnessione delle infrastrutture finanziarie elimina le barriere operative e riduce le commissioni sulle transazioni transfrontaliere, agevolando l'importazione e l'esportazione di beni e servizi tra gli Stati aderenti. L'analisi sottolinea il ruolo chiave della digitalizzazione bancaria nel sostenere l'integrazione economica globale. Lo riferisce Folha de S.Paulo.",
   "more": [
    "Pix è il sistema di pagamento istantaneo sviluppato dalla Banca Centrale del Brasile, diventato uno standard di riferimento per immediatezza e bassi costi. L'interoperabilità tra reti di pagamento internazionali è uno degli obiettivi prioritari delle banche centrali per semplificare le rimesse e gli scambi commerciali."
   ],
