   "titolo": "La Banca Centrale dell'Azerbaigian lancia una gara d'appalto per il supporto del sistema XSOAR",
   "orig": "Azerbaijan’s Central Bank announces tender for XSOAR system support",
   "lead": "La Banca Centrale dell'Azerbaigian ha annunciato l'avvio di una gara d'appalto pubblica finalizzata all'acquisizione di servizi di supporto tecnico e manutenzione per il proprio sistema XSOAR. L'iniziativa rientra nei piani di rafforzamento delle infrastrutture informatiche e della sicurezza digitale dell'istituto finanziario nazionale. L'appalto mira a selezionare fornitori specializzati in grado di garantire la continuità operativa e la protezione dei dati dei sistemi bancari azeri contro le minacce informatiche. Lo riferisce Trend.",
   "more": [
    "I sistemi XSOAR (Extended Security Orchestration, Automation, and Response) sono piattaforme software avanzate utilizzate dalle organizzazioni per automatizzare la risposta agli incidenti di sicurezza informatica. Per gli istituti bancari centrali, l'efficienza di tali strumenti è cruciale per la protezione delle infrastrutture critiche."
   ],
