   "titolo": "Russia, raid notturni contro due sottostazioni in Ucraina e tre navi nel Mar Nero",
   "orig": "Russia Says Hit Power Substations in Ukraine and 3 Ships in Black Sea",
   "lead": "Il ministero della Difesa russo ha dichiarato che le proprie forze hanno condotto una serie di attacchi notturni colpendo tre navi mercantili nel Mar Nero e due sottostazioni elettriche in territorio ucraino. Secondo quanto riferito da Mosca, le imbarcazioni trasportavano equipaggiamenti e rifornimenti bellici destinati a sostenere l'esercito ucraino, mentre le infrastrutture energetiche prese di mira alimentavano stabilimenti legati all'industria della difesa di Kyiv. Le autorità militari russe sostengono che gli obiettivi siano stati neutralizzati per ostacolare la logistica bellica avversaria.",
   "more": [
    "Le operazioni belliche nel Mar Nero e gli attacchi alle infrastrutture di distribuzione elettrica costituiscono due fronti determinanti del conflitto. Mosca colpisce regolarmente le reti energetiche per limitare l'attività delle retrovie e compromettere il supporto logistico e produttivo alle forze schierate sul campo."
   ],
