   "sez": "mondo",
   "titolo": "Usa, Trump frena su nuovi raid contro l'Iran se i negoziati faranno progressi",
   "orig": "Trump tells CNN he is 'highly unlikely' to order Iran attack if talks progress",
   "lead": "Donald Trump ha dichiarato all'emittente Cnn che considera assai improbabile ordinare nuovi interventi militari contro l'Iran se le trattative diplomatiche in corso registreranno passi avanti tangibili. Il presidente statunitense ha spiegato che la decisione dipenderà dalla reale disponibilità di Teheran a sottoscrivere un accordo solido e vincolante in grado di offrire adeguate garanzie internazionali. Le sue parole arrivano in un momento di delicate negoziazioni incentrate sui programmi nucleari iraniani e sulla ricerca di un'intesa volta a stabilizzare l'area ed evitare ulteriori escalation belliche regionali.",
   "more": [
    "Le relazioni diplomatiche tra Washington e Teheran attraversano decenni di forti contrapposizioni su temi quali l'arricchimento dell'uranio, il supporto a gruppi armati regionali e le sanzioni economiche. Gli Stati Uniti alternano pressioni diplomatiche, sanzioni e deterrenza militare per impedire che l'Iran acquisisca capacità atomiche belliche."
   ],
