   "sez": "tech",
   "titolo": "Usa, timori per l'indipendenza del centro per la sicurezza dell'intelligenza artificiale",
   "orig": "AP sources: Staff at U.S. center for AI safety are reporting to the White House, raising independence concerns",
   "lead": "Il personale del Center for Advancing Innovation and Standards for Super Intelligence (CAISSI), sezione formalmente autonoma del Dipartimento del Commercio statunitense, ha ricevuto l'indicazione di riferire in via informale a un ufficio della Casa Bianca. La richiesta ha sollevato forti perplessità tra analisti ed esperti in merito all'effettiva indipendenza dell'organismo, preposto alla definizione di parametri di sicurezza per l'intelligenza artificiale avanzata. Si teme che contatti diretti con la presidenza possano introdurre pressioni politiche nella valutazione degli standard tecnologici. Lo riferisce PBS NewsHour.",
   "more": [
    "I centri governativi per gli standard tecnologici hanno la funzione di testare la robustezza e l'affidabilità dei modelli algoritmici prima della loro diffusione su larga scala. L'autonomia tecnica rispetto agli indirizzi politici è ritenuta fondamentale per garantire valutazioni imparziali e tutelare la sicurezza dei cittadini."
   ],
