   "titolo": "Sudan, l'esercito arresta l'ex leader del partito di governo Ahmed Haroun",
   "orig": "Sudan army detains ex-ruling party leader Ahmed Haroun",
   "lead": "L'esercito del Sudan ha tratto in arresto Ahmed Haroun, figura di vertice dell'ex partito di governo National Congress e stretto collaboratore del deposto dittatore Omar el-Bashir. Haroun, che ha ricoperto ruoli ministeriali all'epoca delle violenze nel Darfur, è destinatario di mandati di cattura emessi dalla Corte penale internazionale con l'accusa di crimini di guerra e crimini contro l'umanità. Il fermo del dirigente politico rappresenta uno sviluppo rilevante nei fragili equilibri interni sudanesi, dove prosegue un sanguinoso conflitto armato tra fazioni militari rivali.",
