   "id": "zc41b2c84",
   "sez": "economia",
   "titolo": "Egitto e Oman avviano colloqui per investimenti congiunti nel settore immobiliare",
   "orig": "Egypt, Oman explore joint investment opportunities in real estate sector",
   "lead": "La ministra dell'Edilizia e delle Infrastrutture egiziana Randa Al-Minshawi ha incontrato al Cairo l'ambasciatore dell'Oman e una delegazione ministeriale del sultanato per esaminare opportunità di partenariato economico nel settore dello sviluppo urbano e delle costruzioni. Alla missione hanno preso parte i responsabili di una ventina di primarie aziende immobiliari omanite interessate a investire in progetti residenziali e commerciali in territorio egiziano. L'incontro rientra nella strategia di rafforzamento delle relazioni commerciali bilaterali e di attrazione di capitali privati nel mercato delle grandi opere urbane.",
   "more": [
    "I paesi dell'area mediorientale promuovono forme crescenti di cooperazione economica per favorire la diversificazione degli investimenti. L'Egitto ha intrapreso vasti programmi di espansione urbanistica ed edilizia per ammodernare le proprie città e attrarre finanziamenti stabili provenienti dai fondi d'investimento e dalle imprese del Golfo."
   ],
