   "titolo": "Cile, il governo promuove la Giornata della famiglia tra le polemiche politiche",
   "orig": "Gobierno celebra primer Día Nacional del Encuentro Familiar con más de 150 actividades gratuitas",
   "lead": "Il governo cileno ha celebrato la prima Giornata nazionale dell'incontro familiare promuovendo oltre centocinquanta iniziative gratuite su tutto il territorio del paese. L'appuntamento pubblico ha tuttavia suscitato rilievi critici da parte di alcune formazioni di opposizione, emerse nel quadro delle tensioni provocate dalle recenti discussioni sui provvedimenti di riduzione delle pene carcerarie. La ministra dello Sviluppo Sociale ha respinto le obiezioni, ricordando che la legge istitutiva della ricorrenza è stata approvata all'unanimità dal Congresso con il consenso di ogni gruppo parlamentare. Lo riferisce La Tercera.",
   "more": [
    "In Cile, le attività promosse dal ministero dello Sviluppo Sociale puntano a sostenere i legami comunitari e la partecipazione civica attraverso programmi aperti alla cittadinanza. Il confronto politico interno tende tuttavia a polarizzarsi frequentemente quando gli eventi pubblici incrociano temi sensibili legati alla sicurezza e alle decisioni giudiziarie."
   ],
