   "id": "zec3d2da4",
   "sez": "cultura",
   "titolo": "Perù, un saggio di Farid Kahhat analizza la perdita di certezze nell'ordine mondiale",
   "orig": "\"El mundo se ha vuelto un lugar extraño\": el desconcierto que genera el fin de las viejas certezas",
   "lead": "Nel saggio intitolato \"Il mondo è diventato un luogo strano\", il docente peruviano di relazioni internazionali Farid Kahhat esamina il crescente disorientamento globale generato dal tramonto delle certezze che hanno orientato i rapporti tra gli Stati negli ultimi decenni. L'analista accademico evidenzia evidenti passi indietro nel sistema delle regole internazionali, pur escludendo che la situazione attuale replichi fedelmente il clima del periodo interbellico del Novecento. L'opera offre una lettura critica dei cambiamenti geopolitici che stanno ridefinendo la sicurezza e gli assetti politici su scala planetaria.",
   "more": [
    "L'assetto internazionale emerso dopo la seconda guerra mondiale si basava su istituzioni multilaterali, norme condivise e accordi di sicurezza collettiva. La moltiplicazione di conflitti regionali e l'emergere di nuove rivalità tra potenze stanno mettendo in crisi l'efficacia di questi organismi, alimentando riflessioni tra politologi e storici."
   ],
