   "id": "z79ac4989",
   "sez": "mondo",
   "titolo": "Venezuela, María Corina Machado visita la zona colpita dai terremoti a Caracas",
   "orig": "María Corina Machado visitó San Bernardino y se reunió con afectados por los terremotos",
   "lead": "La leader dell'opposizione venezuelana María Corina Machado si è recata nella parrocchia di San Bernardino, a Caracas, per incontrare le persone colpite dai recenti terremoti che hanno interessato l'area metropolitana. Durante la visita nei quartieri maggiormente danneggiati dal sisma, l'esponente politica ha ascoltato le testimonianze degli abitanti che hanno registrato perdite familiari e subito gravi danni strutturali alle proprie case. L'incontro ha inteso portare vicinanza alle comunità rimaste prive di alloggio e attirare l'attenzione sulle carenze nei soccorsi e negli interventi di ripristino.",
   "more": [
    "Le calamità naturali nei centri urbani del Venezuela amplificano le difficoltà di una popolazione già provata da anni di crisi socioeconomica. La vulnerabilità del patrimonio immobiliare e i limiti delle risorse per la protezione civile rendono complessa la gestione delle emergenze e l'assistenza rapida agli sfollati."
   ],
