   "id": "zbb6b151e",
   "sez": "ambiente",
   "titolo": "Bolivia, le Forze armate coordinano i piani per fronteggiare il fenomeno di El Niño",
   "orig": "FFAA coordina la planificación preventiva para enfrentar el fenómeno de El Niño",
   "lead": "I comandi delle Forze armate della Bolivia hanno avviato il coordinamento dei piani preventivi per contrastare gli effetti ambientali attesi con l'insorgere del fenomeno climatico di El Niño. L'esecutivo boliviano ha formalizzato lo stato di emergenza sul territorio nazionale a causa delle proiezioni meteorologiche che indicano possibili eventi atmosferici estremi, tra cui intense alluvioni o periodi di grave siccità. Le strutture militari collaborano con le autorità civili per disporre le risorse logistiche necessarie a tutelare le comunità rurali e mitigare i danni alle coltivazioni. Lo riferisce El Deber.",
   "more": [
    "El Niño è un'oscillazione climatica periodica caratterizzata dal riscaldamento delle acque nell'Oceano Pacifico equatoriale. I suoi effetti provocano rilevanti alterazioni nelle precipitazioni globali, con conseguenze spesso pesanti per i paesi andini su agricoltura, disponibilità idrica e gestione del territorio."
   ],
