   "titolo": "Bolivia, l'opposizione critica il primo anno di presidenza di Paz",
   "orig": "Samuel y Tuto cuestionan el primer año de Paz y afirman que no hubo el cambio esperado",
   "lead": "Al compimento del primo anno di mandato del presidente della Bolivia Paz, i leader dell'opposizione Samuel Doria Medina e Jorge Tuto Quiroga hanno espresso severe valutazioni, sostenendo che non sia stato attuato il cambiamento promesso ai cittadini. Entrambi gli esponenti politici hanno evidenziato la persistente carenza di riforme strutturali nell'economia e nelle istituzioni, accusando il governo di mantenere un impianto statista e centralista privo di una strategia chiara. Le forze critiche hanno sollecitato un deciso cambio di rotta per favorire la crescita e abbandonare pratiche clientelari.",
   "more": [
    "La Bolivia attraversa una complessa fase di transizione economica, condizionata dal calo delle riserve valutarie e dalla necessità di ammodernare i settori produttivi. Il dibattito politico ruota attorno al bilanciamento tra l'intervento pubblico dello Stato nell'economia e l'apertura a investimenti del settore privato."
   ],
