   "id": "z0106da7e",
   "sez": "sport",
   "titolo": "Tenerife, commosso tributo di tifosi e compagni per Jesús De Miguel",
   "orig": "Tenerife’s Jesus De Miguel honoured in tearful tribute by teammates, fans",
   "lead": "I compagni di squadra e i sostenitori del Tenerife hanno reso un toccante omaggio a Jesús De Miguel durante una cerimonia commemorativa segnata da grande commozione. Nel corso dell'evento, i calciatori hanno faticato a trattenere le lacrime mentre i tifosi presenti intonavano cori dedicati al giocatore. I vertici della società calcistica spagnola hanno voluto esprimere vicinanza pubblica ai familiari di De Miguel, assicurando che il club garantirà loro pieno sostegno e vicinanza in questo momento doloroso. Lo riferisce Al Jazeera.",
   "more": [
    "Nel calcio professionistico le cerimonie commemorative rappresentano un momento di forte aggregazione tra la tifoseria e i membri della società. I club sportivi spesso mantengono canali di supporto formali per le famiglie dei propri tesserati coinvolti in eventi luttuosi, promuovendo iniziative di solidarietà e tributi all'interno degli stadi durante le competizioni ufficiali."
   ],
