   "id": "zf0628828",
   "sez": "sport",
   "titolo": "Tennis, la statunitense Claire Liu si aggiudica l'Open di Hong Kong contro Alex Eala",
   "orig": "Tearful Alex Eala loses Hong Kong Open final to Claire Liu in straight sets",
   "lead": "La tennista filippina Alex Eala è stata sconfitta nella finale dell'Open di Hong Kong dalla statunitense Claire Liu con il punteggio netto di 6-3, 6-0. La giovane atleta asiatica, visibilmente commossa dopo la battuta d'arresto, non è riuscita a contrastare il gioco dell'avversaria, numero 102 della classifica mondiale, che ha dominato l'incontro in due set consecutivi. Il risultato ha interrotto l'ottimo percorso della promessa filippina all'interno del torneo disputato nella metropoli asiatica. Lo riferisce Al Jazeera.",
   "more": [
    "Il circuito tennistico professionistico femminile offre tornei internazionali che permettono alle giovani atlete emergenti di accumulare punti preziosi per il ranking mondiale. La vittoria di Claire Liu sottolinea l'importanza dell'esperienza nelle fasi decisive delle finali, dove la gestione della pressione emotiva gioca spesso un ruolo determinante nell'esito dei match."
   ],
