   "id": "zcf0d23cd",
   "sez": "mondo",
   "titolo": "Stati Uniti, annunciata la task force Iron Gate per fermare le armi iraniane",
   "orig": "US task force to cut off Iran’s transport of advanced weapons: What we know",
   "lead": "Il governo di Washington ha annunciato la costituzione di una nuova unità operativa speciale, denominata Task Force Iron Gate, con l'obiettivo di intercettare e bloccare i carichi marittimi di armamenti sofisticati provenienti dall'Iran. L'iniziativa militare nasce nel contesto di crescenti timori per una possibile escalation delle tensioni nelle rotte marittime strategiche del Medio Oriente. Le autorità statunitensi intendono aumentare il monitoraggio per impedire che sistemi d'arma avanzati raggiungano gruppi alleati di Teheran nell'area regionale. Lo riferisce Al Jazeera.",
   "more": [
    "Il monitoraggio dei corridoi marittimi mediorientali, in particolare vicino allo Stretto di Hormuz e al Mar Rosso, è storicamente coordinato da flotte multinazionali a guida statunitense. L'interdizione dei rifornimenti militari a Teheran e alle sue milizie mira a tutelare le rotte commerciali internazionali e la sicurezza della navigazione mercantile globale."
   ],
