   "id": "ze158c22d",
   "sez": "mondo",
   "titolo": "Iraq, lo scontro politico nel Kurdistan riaccende il timore di una divisione",
   "orig": "Could Iraq’s Kurdish region return to two separate administrations?",
   "lead": "Un profondo stallo politico tra il Governo Regionale del Kurdistan e l'Unione Patriottica del Kurdistan minaccia la stabilità istituzionale del nord dell'Iraq, sollevando lo spettro di un ritorno a due amministrazioni territoriali distinte. Le divergenze tra le principali forze politiche curde mettono a rischio l'unità della regione semiautonoma, riaprendo vecchie fratture amministrative e decisionali. La mancanza di intesa indebolisce la gestione centralizzata dei servizi e del potere locale, alimentando incertezze sul futuro assetto di governo dell'intera area settentrionale irachena. Lo riferisce Al Jazeera.",
   "more": [
    "La regione autonoma del Kurdistan iracheno ha vissuto una divisione formale negli anni Novanta tra le sfere di influenza del Partito Democratico Curdo a Erbil e dell'Unione Patriottica del Kurdistan a Sulaymaniyya. Nonostante l'unificazione successiva alla caduta del regime di Saddam Hussein, le tensioni sulla ripartizione delle risorse energetiche e finanziarie continuano a frammentare la leadership locale."
   ],
