   "id": "z64cc7008",
   "sez": "prima",
   "titolo": "Papa Leone XIV in Argentina: atteso il confronto istituzionale con il presidente Milei",
   "orig": "Papa vola in Argentina, vedrà Milei",
   "lead": "Il Papa è arrivato in Argentina per una storica visita apostolica che culminerà in un atteso vertice istituzionale con il presidente Javier Milei. Il viaggio del pontefice, iniziato dopo la conclusione delle celebrazioni ufficiali in Uruguay, tocca una nazione attraversata da forti tensioni sociali e politiche dovute alle misure di rigore economico varate dal governo libertario. Il programma dei quattro giorni prevede una sosta simbolica al Cottolengo Don Orione e importanti messe all'aperto a Palermo, Cordova e Luján, in un clima di forte contrapposizione tra la dottrina sociale cattolica e l'agenda ultraliberista.",
   "more": [
    "La visita papale in Argentina assume un significato che supera la dimensione religiosa a causa della polarizzazione interna. Le riforme economiche e i tagli alla spesa pubblica promossi dall'esecutivo Milei contrastano con la tradizione pastorale della Chiesa locale, storicamente impegnata nel welfare e nella tutela delle fasce sociali più indigenti attraverso una capillare rete comunitaria."
   ],
