   "id": "z705c5133",
   "sez": "economia",
   "titolo": "Corea del Nord, le requisizioni forzate di grano fanno impennare i prezzi del riso",
   "orig": "Empty-handed farmers drive up rice prices",
   "lead": "Nella provincia nordcoreana dello Hwanghae meridionale, i lavoratori agricoli si stanno riversando nei mercati locali per comprare riso, dopo che i rigidi sequestri di grano operati dallo Stato li hanno lasciati privi di scorte dal raccolto annuale. La corsa agli acquisti ha fatto schizzare le quotazioni del cereale oltre i cinquantamila won al chilogrammo nei mercati privati, toccando in alcune aree persino i sessantamila won. Le forzate requisizioni statali hanno privato i contadini dei mezzi minimi di sussistenza immediata. Lo riferisce Daily NK.",
   "more": [
    "Il sistema di approvvigionamento statale in Corea del Nord impone quote obbligatorie di conferimento alle cooperative agricole, spesso lasciando ai contadini quantitativi insufficienti per il consumo personale. Tale carenza costringe i produttori a rifornirsi sui mercati informali, dove i prezzi fluttuano rapidamente in base alla scarsità dei beni di prima necessità."
   ],
