   "id": "z3b353b6a",
   "sez": "mondo",
   "titolo": "RD Congo, l'Assemblea nazionale propone cinque nuove personalità come eroi nazionali",
   "orig": "L’Assemblée nationale propose cinq nouvelles personnalités au rang de Héros nationaux",
   "lead": "L'Assemblea nazionale della Repubblica Democratica del Congo ha esaminato e approvato una proposta volta a elevare cinque figure storiche al rango di eroi nazionali. Tra le personalità selezionate dal parlamento di Kinshasa figura anche lo storico oppositore e leader politico Étienne Tshisekedi wa Mulumba. L'iniziativa legislativa intende rendere omaggio al contributo civile e politico offerto da queste personalità alla storia e alla democrazia del Paese africano, formalizzandone il riconoscimento istituzionale attraverso lo status onorifico più elevato previsto dall'ordinamento statale.",
   "more": [
    "Il titolo di eroe nazionale nella Repubblica Democratica del Congo è una delle massime onorificenze della Repubblica, storicamente riservata a figure chiave dell'indipendenza come Patrice Lumumba. L'inclusione di Étienne Tshisekedi riconosce decenni di lotta pacifica per il multipartitismo e la democrazia condotta contro i regimi autoritari che si sono succeduti nel Paese."
   ],
