   "id": "z66404a7f",
   "sez": "sport",
   "titolo": "Calcio, l'Egitto esonera il commissario tecnico Hossam Hassan dopo le polemiche personali",
   "orig": "Hossam Hassan sacked as Egypt head coach over ex-wife scandal",
   "lead": "La Federazione calcistica egiziana ha sollevato ufficialmente dall'incarico il commissario tecnico della nazionale Hossam Hassan e il suo staff, affidando la panchina ad interim ad Ali Maher in vista delle qualificazioni per la Coppa d'Africa. La decisione dei vertici federali è maturata in seguito all'impatto negativo causato dalle recenti controversie legate alla vita privata dell'allenatore e a precedenti dissidi disciplinari. Nonostante i risultati positivi ottenuti sul campo, la federazione ha optato per un cambio immediato alla guida tecnica della selezione nazionale.",
   "more": [
    "Hossam Hassan è considerato una delle massime leggende del calcio egiziano e africano per i suoi primati di presenze e reti con i Faraoni. Tuttavia, la sua gestione della panchina è stata spesso accompagnata da tensioni caratteriali e accese discussioni con la federazione, fattori che hanno pesato sulla decisione di interrompere anticipatamente il contratto."
   ],
