   "id": "z91aece5d",
   "sez": "musica",
   "titolo": "Regno Unito, Skepta pubblica il nuovo album dopo sette anni e celebra le sue origini",
   "orig": "Skepta: 'I'm what it looks like if you give an immigrant child a chance'",
   "lead": "Il musicista britannico Skepta, annoverato tra i principali interpreti ed esponenti di punta del genere grime, fa il proprio ritorno discografico con il primo album in studio dopo un'assenza durata sette anni. Presentando la nuova opera musicale, l'artista ha voluto riflettere pubblicamente sulle proprie radici e sul percorso personale compiuto, dichiarando di incarnare il risultato positivo che si ottiene quando viene concessa una reale opportunità al figlio di persone immigrate. Il nuovo progetto segna una tappa significativa nella carriera del rapper londinese. Lo riferisce BBC News.",
   "more": [
    "Il grime è un genere musicale nato nei primi anni Duemila nei quartieri popolari di Londra, caratterizzato da ritmiche elettroniche veloci e testi che raccontano le dinamiche urbane. Skepta ne è stato un pioniere fondamentale, capace di portare questa cultura underground a un pubblico internazionale e ai massimi riconoscimenti discografici."
   ],
