   "id": "zfacd4079",
   "sez": "spazio",
   "titolo": "Astronomia, il telescopio ELT sonderà i misteri della materia oscura nelle galassie diffuse",
   "orig": "The ELT Can Probe Ultra-Diffuse Galaxies and Their Dark Matter Mysteries",
   "lead": "Una nuova proposta strumentale destinata all'Extremely Large Telescope potrebbe presto consentire agli astrofisici di osservare con precisione inedita le galassie ultra-diffuse, strutture cosmiche grandi quanto la Via Lattea ma con un numero estremamente ridotto di stelle. La conformazione apparentemente rarefatta di questi corpi celesti continua a interrogare la comunità scientifica, poiché analizzarne l'evoluzione potrebbe confermare la validità del modello cosmologico standard Lambda-CDM. Il futuro telescopio offrirà una risoluzione ideale per verificare la presenza e la distribuzione della materia oscura in tali ammassi.",
   "more": [
    "L'Extremely Large Telescope è un osservatorio astronomico terrestre di ultima generazione attualmente in costruzione nel deserto di Atacama, in Cile, sotto la guida dello European Southern Observatory. Grazie al suo specchio primario di circa quaranta metri di diametro, permetterà indagini dettagliate sulle strutture più deboli e distanti dell'universo."
   ],
