   "id": "z03c3088d",
   "sez": "economia",
   "titolo": "Egitto, la National Bank of Egypt alza i rendimenti sui certificati di deposito Platinum",
   "orig": "National Bank of Egypt increases yield on Platinum certificates",
   "lead": "L'istituto di credito National Bank of Egypt ha deliberato un incremento di un punto percentuale sul rendimento annuo dei propri certificati di deposito a tasso fisso della linea Platinum. A seguito dell'aggiornamento, il tasso d'interesse sale al 18,75 percento per i titoli che prevedono la liquidazione mensile delle cedole e raggiunge il 18,85 percento per i certificati con rendicontazione su base trimestrale. La misura intende rendere più attraenti gli strumenti di risparmio per la clientela bancaria nazionale. Lo riferisce Egypt Independent.",
   "more": [
    "I certificati di deposito bancari a tasso fisso costituiscono uno strumento diffuso per incentivare il risparmio delle famiglie e contrastare la pressione inflazionistica. In Egitto, le banche di proprietà pubblica utilizzano spesso rialzi dei rendimenti sui depositi per assorbire la liquidità presente sul mercato e sostenere la moneta locale."
   ],
