   "titolo": "Giappone, annunciato il progetto multimediale Harajuku Himegoto House con serie anime",
   "orig": "Harajuku Himegoto House Multimedia Project Announced",
   "lead": "La società di intrattenimento giapponese Plott ha annunciato il lancio ufficiale del nuovo progetto multimediale intitolato Harajuku Himegoto House, rivelando la produzione di un adattamento anime per la televisione. La vicenda ruota attorno alle curiose avventure di un gruppo di sicari che lavorano all'interno di un locale a tema nel celebre quartiere di Harajuku. Insieme all'annuncio sono stati svelati il primo video promozionale teaser, la locandina ufficiale e i nomi dei principali doppiatori e membri dello staff tecnico coinvolti nella realizzazione.",
   "more": [
    "I progetti crossmediali nell'industria dell'animazione giapponese combinano contemporaneamente la produzione di serie animate, fumetti, musica e merchandise promozionale. Questo modello produttivo coinvolge studi specializzati e doppiatori famosi fin dalle fasi iniziali per costruire un seguito di appassionati attraverso diverse piattaforme commerciali e canali digitali."
   ],
