   "sez": "ingegneria",
   "titolo": "Portogallo, Fala Atelier progetta un rifugio per nomadi digitali incastonato nella collina",
   "orig": "Fala Atelier embeds trio of playful volumes into Portuguese hillside for Cookie Cutter Retreat",
   "lead": "Lo studio di architettura portoghese Fala Atelier, con base a Porto, ha completato la realizzazione di Cookie Cutter Retreat, una residenza pensata per accogliere nomadi digitali integrandosi nel pendio collinare. Il complesso si caratterizza per l'impiego di tre distinti volumi semicircolari di dimensioni variabili, inseriti in modo originale nel terreno circostante per definire gli spazi abitativi e di lavoro. L'intervento punta a coniugare forme geometriche rigorose e sperimentazione formale con il contesto naturale del paesaggio rurale in cui sorge la struttura. Lo riferisce Dezeen.",
   "more": [
    "L'architettura contemporanea per il lavoro a distanza sperimenta sempre più soluzioni residenziali flessibili e integrate nel paesaggio. L'uso di volumi geometrici puri permette di ottimizzare la luce naturale e di definire aree funzionali distinte tra concentrazione professionale e vita quotidiana, riducendo al contempo l'impatto visivo sui rilievi collinari circostanti."
   ],
