   "sez": "dibattito",
   "titolo": "Estonia, dibattito sull'estensione delle lezioni dedicate ai dialetti regionali a scuola",
   "orig": "New Estonian dialect lesson rules raise questions among teachers, students",
   "lead": "In Estonia è in corso un confronto pubblico sulla nuova bozza di legge presentata dal Ministero dell'Istruzione, volta a espandere l'insegnamento dei dialetti regionali nei programmi scolastici del Paese. L'iniziativa ministeriale intende preservare e promuovere le varianti linguistiche locali nelle classi, ma il piano ha suscitato perplessità tra docenti e dirigenti scolastici. Secondo gli insegnanti e i responsabili degli istituti, l'introduzione di queste norme solleva interrogativi organizzativi riguardanti la gestione degli orari, le risorse a disposizione e l'effettivo carico di studio per gli studenti. Lo riferisce ERR News.",
   "more": [
    "La tutela delle varietà linguistiche e dei dialetti storici rappresenta un tema centrale nelle politiche educative europee, dove si cerca di bilanciare la salvaguardia del patrimonio culturale immateriale con la padronanza della lingua nazionale standard. In diversi Paesi del continente, l'inserimento curricolare delle parlate regionali richiede spesso una revisione delle competenze del corpo docente e un coordinamento con le comunità locali per evitare discrepanze didattiche tra territori diversi."
   ],
