   "id": "z7a99c3d1",
   "sez": "adolescenti",
   "titolo": "Regno Unito, le celebrazioni del Remembrance Sunday per ricordare i caduti militari",
   "orig": "Remembrance Sunday in pictures",
   "lead": "Nel Regno Unito e in varie comunità nel mondo si sono svolte le tradizionali cerimonie del Remembrance Sunday, la giornata dedicata a onorare la memoria di tutti coloro che hanno perso la vita prestando servizio nelle forze armate. Le celebrazioni sono state raccontate attraverso una galleria di immagini che mostrano i momenti di raccoglimento, i due minuti di silenzio osservati dai cittadini e la deposizione delle consuete corone di papaveri rossi presso i monumenti ai caduti sparsi sul territorio. Lo riferisce BBC Newsround.",
   "more": [
    "Il Remembrance Sunday si celebra ogni anno la seconda domenica di novembre, in concomitanza temporale con l'anniversario della fine della Prima guerra mondiale nel 1918. Il papavero rosso è diventato il simbolo universale di questa ricorrenza nel mondo anglosassone, ispirato dalle celebri poesie che descrivevano i fiori cresciuti sui campi di battaglia delle Fiandre."
   ],
