   "orig": "Lucky Bird Found in Storm Drain a Mile From Home After Passing Driver Happens to Spot it Hopping in",
   "lead": "A Northampton, in Inghilterra, un parrocchetto domestico di nome Luna è stato ritrovato vivo all'interno di uno scolo fognario a circa un miglio dalla sua abitazione. Il volatile era fuggito dopo che i forti venti provocati dalla tempesta Boelo avevano spalancato la finestra della cucina della proprietaria Cimberley Frost. L'animale è stato individuato grazie all'attenzione di un automobilista di passaggio, che lo ha notato mentre saltellava dentro lo scarico dell'acqua, permettendo così il recupero del piccolo volatile smarrito. Lo riferisce Good News Network.",
