   "orig": "“Ho dormito su tutti i tappeti del ristorante”. La vita nascosta di Ciccio Sultano, che a 9 anni faceva il muratore",
   "lead": "Lo chef siciliano Ciccio Sultano, titolare di due stelle Michelin, ha condiviso pubblicamente i retroscena della propria infanzia e il percorso professionale che lo ha portato ai massimi vertici della ristorazione. Il cuoco ha ricordato che all'età di nove anni lavorava già come muratore e che a sedici anni viveva da solo. Tra i sacrifici affrontati per affermarsi, Sultano ha descritto la fatica degli esordi, trascorsi crescendo senza il padre e arrivando a dormire su tutti i tappeti del proprio locale per inseguire la carriera. Lo riferisce Gambero Rosso.",
