   "orig": "Lele Mora ricoverato a Roma per un ictus, \"sono vivo per miracolo\"",
   "lead": "L'ex agente dello spettacolo Lele Mora è ricoverato a Roma presso il Policlinico Umberto I a seguito di un ictus. Il ricovero nella struttura sanitaria della capitale è iniziato alla fine del mese di ottobre. A dare notizia dell'accaduto è stato il quotidiano Il Messaggero, a cui lo stesso Mora ha rilasciato una breve dichiarazione spiegando di considerarsi vivo per miracolo dopo il grave problema di salute che lo ha colpito e che ha reso necessarie cure ospedaliere prolungate. Lo riferisce ANSA.",
