   "orig": "Babiš to visit Israel to discuss air defence system",
   "lead": "Il leader politico ceco Andrej Babiš ha programmato una missione ufficiale in Israele allo scopo di affrontare discussioni sui sistemi di difesa aerea. L'incontro diplomatico ha come obiettivo centrale l'approfondimento delle cooperazioni in materia di sicurezza e delle dotazioni tecnologiche nel campo della difesa da attacchi aerei. I colloqui tra la rappresentanza ceca e le controparti israeliane verificheranno i possibili sviluppi operativi e le opzioni tecniche per proteggere lo spazio aereo da potenziali minacce esterne. Lo riferisce Radio Prague International.",
