   "titolo": "In Bhutan recinzioni elettriche a difesa dei campi di Samdrup Jongkhar",
   "orig": "Electric fencing benefits 59 households in Orong Gewog, Samdrup Jongkhar",
   "lead": "Nel gewog di Orong, all'interno del distretto di Samdrup Jongkhar in Bhutan, cinquantanove nuclei familiari beneficiano dell'installazione di recinzioni elettriche volte a proteggere i raccolti agricoli dalla fauna selvatica. Prima di questo intervento, per gli agricoltori locali salvaguardare le coltivazioni richiedeva una costante attività di sorveglianza dei campi, che toglieva tempo prezioso alla cura ordinaria della terra. La nuova barriera difensiva ha ridotto significativamente le incursioni degli animali selvatici, rendendo il lavoro degli abitanti meno gravoso e più sicuro. Lo riferisce Bhutan Broadcasting Service.",
