   "titolo": "Islanda in van per sette giorni a caccia dell'aurora boreale",
   "orig": "Abbiamo scelto la settimana giusta per vivere l’aurora boreale in Islanda: il nostro viaggio in van di 7 giorni nell’isola dei vulcani",
   "lead": "Un itinerario di sette giorni a bordo di un van ha attraversato l'Islanda per seguire e osservare lo spettacolo naturale dell'aurora boreale. Il viaggio su strada ha comportato l'attraversamento di paesaggi vulcanici tipici dell'isola, sfidando condizioni meteorologiche mutevoli caratterizzate da vento sostenuto e nevicate. I partecipanti hanno descritto l'esperienza sottolineando l'importanza di aver individuato il periodo settimanale ideale per compiere l'esplorazione, riuscendo ad ammirare il fenomeno luminoso notturno che rende celebre la destinazione tra i viaggiatori di tutto il mondo. Lo riferisce Turisti per Caso.",
