   "titolo": "L'architettura moderna riprende i principi delle civiltà mesoamericane",
   "orig": "Five examples of Mesoamerican modern architecture",
   "lead": "In Messico diversi architetti contemporanei stanno riscoprendo e applicando elementi tradizionali dell'architettura precolombiana, combinandoli con tecniche costruttive all'avanguardia. All'interno del libro intitolato Mesoamerican Modern, la curatrice e scrittrice Su Wu ha selezionato cinque progetti emblematici per spiegare questa tendenza progettuale. Le opere analizzate dimostrano come le nozioni costruttive delle antiche civiltà della regione possano integrarsi con i linguaggi del design moderno, dando vita a edifici contemporanei che mantengono un forte legame identitario con la storia e le forme del passato mesoamericano. Lo riferisce Dezeen.",
