   "lead": "Le procedure per il reclutamento del personale docente nelle scuole italiane sono state al centro della trasmissione Question Time, con la partecipazione della segretaria nazionale del sindacato ANIEF Chiara Cozzetto. Durante l'incontro sono state esaminate le opportunità di assunzione rivolte a coloro che sono risultati idonei ai concorsi ordinari già svolti. L'attenzione si è concentrata sul funzionamento degli elenchi regionali e sui criteri che determineranno la scelta delle classi di concorso per i prossimi bandi attesi dagli aspiranti insegnanti. Lo riferisce Orizzonte Scuola.",
