   "sez": "dibattito",
   "titolo": "Cipro, il ministero difende la riforma sulle nomine dei docenti",
   "orig": "Ministry insists proposal for teacher appointments is fair",
   "lead": "A Cipro il ministero dell'Istruzione difende la propria proposta sul sistema di nomina dei docenti, definendola equa ed equilibrata. Secondo le autorità cipriote, il piano persegue l'obiettivo di garantire le assunzioni del personale che già presta servizio nelle scuole pubbliche, offrire pari opportunità alle nuove generazioni di insegnanti e assicurare un organico regolare negli istituti. Il confronto riguarda le regole per stabilizzare i precari storici senza precludere l'accesso ai concorsi ai neolaureati. Il ministero afferma che il criterio individuato bilancia le due esigenze. Lo riferisce Cyprus Mail.",
   "more": [
    "I sistemi di assunzione del corpo docente nelle scuole pubbliche europee oscillano costantemente tra due principi: la tutela dei diritti acquisiti dagli insegnanti precari di lungo corso e la selezione concorsuale basata sul merito aperta ai nuovi candidati. Trovare una formula gradita a entrambe le categorie rappresenta spesso una delle vertenze sindacali e politiche più complesse per i governi."
   ],
