   "id": "z93ac91d9",
   "sez": "cultura",
   "titolo": "La ricorrenza di Diwali celebrata dalle comunità indù nel mondo",
   "orig": "What is Diwali, the Festival of Lights, and how is it celebrated?",
   "lead": "La comunità indù celebra nel mese di novembre la festa di Diwali, conosciuta anche come la festa delle luci, una delle più rilevanti ricorrenze del calendario religioso. La festività segue l'andamento del calendario lunare e si colloca abitualmente tra la fine di ottobre e l'inizio del mese successivo. La celebrazione, accompagnata dall'accensione rituale di lampade e momenti conviviali, rappresenta simbolicamente la vittoria della luce sull'oscurità. Nelle città occidentali l'evento registra una partecipazione ampia ma non priva talvolta di tensioni politiche locali.",
   "more": [
    "Diwali è una festività celebrata da milioni di persone di religione indù, giainista e sikh in tutto il mondo. Il rituale principale consiste nell'accendere piccole lampade d'olio in terracotta, chiamate diya, per simboleggiare la vittoria del bene sul male e della conoscenza sull'ignoranza, segnando spesso l'inizio di un nuovo anno finanziario tradizionale."
   ],
