   "titolo": "Settimana bianca più cara: skipass in aumento del 43% in cinque anni",
   "orig": "Prezzi, Assoutenti: è sempre più caro-neve. Nuovi rincari per tariffe skipass, in 5 anni aumenti arrivano al +43%",
   "lead": "I costi per le vacanze invernali continuano a crescere in Italia. Secondo i dati elaborati dall'associazione di consumatori Assoutenti, le tariffe degli skipass hanno registrato forti rincari, raggiungendo un aumento complessivo del 43% negli ultimi cinque anni. Il fenomeno del rincaro neve incide sensibilmente sui bilanci familiari, portando circa due milioni di italiani a rinunciare alla settimana bianca rispetto all'epoca precedente alla pandemia di Covid-19. La tendenza agli aumenti generalizzati dei prezzi investe vari settori dei consumi turistici e della spesa programmata per la stagione invernale. Lo riferisce Il Sole 24 Ore.",
   "more": [
    "L'incremento dei costi di gestione per gli impianti sciistici è legato in gran parte alle bollette energetiche per il funzionamento degli impianti di risalita e per l'innevamento artificiale, reso sempre più necessario dalle scarse precipitazioni e dalle temperature elevate dovute al cambiamento climatico. Tali costi operativi si riflettono inevitabilmente sui prezzi finali dei biglietti per gli utenti."
   ],
