   "titolo": "I moscardini prosperano nella tenuta di Killerton del National Trust",
   "orig": "Dormice 'thrive' at National Trust site",
   "lead": "Nel Devon, in Inghilterra, le popolazioni di moscardino comune mostrano una significativa crescita all'interno della tenuta di Killerton, gestita dal National Trust. L'area protetta ospita circa cento cassette nido distribuite nel bosco per favorire il monitoraggio e la riproduzione di questi piccoli mammiferi arboricoli. Gli esperti dell'ente hanno verificato la buona salute della colonia, sottolineando come la corretta manutenzione dell'habitat forestale e la disponibilità di rifugi sicuri consentano alla specie protetta di vivere e riprodursi con successo nell'ecosistema locale. Lo riferisce BBC News.",
