   "titolo": "Dustin Hoffman pubblica la sua prima autobiografia 'Look at me'",
   "orig": "Dustin Hoffman si racconta per la prima volta dietro la leggenda in 'Look at me'",
   "lead": "L'attore statunitense Dustin Hoffman racconta per la prima volta i dettagli della propria vita e carriera dietro l'immagine pubblica nel libro autobiografico Look at me. Il volume di memorie, scritto a quattro mani insieme all'autrice Ariel Levy, viene pubblicato sul mercato editoriale a partire dal 10 novembre e sarà distribuito nelle librerie italiane dalla casa editrice Rizzoli. L'opera promette di svelare gli aspetti privati, le difficoltà e i momenti fondamentali del celebre interprete hollywoodiano, vincitore di molteplici premi Oscar. Lo riferisce ANSA.",
