   "orig": "Black panther seen again in Kaeng Krachan park",
   "lead": "Una pantera nera è stata nuovamente avvistata nella provincia di Phetchaburi, all'interno del parco nazionale di Kaeng Krachan, la riserva naturale più vasta della Thailandia. L'incontro visivo con il felino testimonia l'elevato livello di biodiversità custodito nell'area protetta, che rappresenta uno dei rifugi ideali per predatori elusivi e rari. La presenza documentata del grande felino ha attirato l'attenzione delle autorità forestali locali e dei biologi, confermando l'importanza della conservazione delle foreste pluviali thailandesi contro la deforestazione e il bracconaggio. Lo riferisce Bangkok Post.",
