   "orig": "Florian Residence 1 / Benthem Crouwel Architects",
   "lead": "A Bratislava, nelle vicinanze della Banca Nazionale di Slovacchia, sono stati ultimati i lavori del Florian Residence 1, primo edificio completato di un piano di rigenerazione urbana progettato dallo studio Benthem Crouwel Architects. La struttura si articola su otto piani e comprende negozi, spazi comuni e settantatré appartamenti di diversa metratura. L'edificio adotta elevati standard tecnici con tripli vetri, avanzati sistemi di isolamento termico e soluzioni per il comfort acustico, arricchiti da un grande atrio luminoso d'ingresso concepito per favorire la vivibilità dei residenti. Lo riferisce ArchDaily.",
