   "orig": "Matematica Senza Frontiere 2026/27, al via la XXXVI edizione per le scuole primarie e secondarie. Previsto anche il concorso LOGO MsF 2027",
   "lead": "Per l'anno scolastico 2026/2027 è stata avviata la trentaseiesima edizione di Matematica Senza Frontiere, la competizione nazionale destinata agli alunni delle scuole primarie e degli istituti secondari italiani. L'iniziativa educativa è promossa dall'Ufficio Scolastico Regionale per la Lombardia per stimolare l'apprendimento della disciplina scientifica attraverso prove di gruppo e lavoro cooperativo tra studenti. In parallelo alla gara didattica sui quesiti matematici, è stato indetto anche il concorso creativo per la realizzazione del logo ufficiale dell'edizione 2027 della manifestazione scolastica. Lo riferisce Orizzonte Scuola.",
