   "lead": "L'adattamento anime della serie Spy×Family continuerà con una quarta stagione televisiva e con l'uscita nelle sale cinematografiche di un nuovo film d'animazione prevista per il 2027. L'annuncio ufficiale è stato accompagnato dalla pubblicazione di una prima immagine promozionale dedicata ai prossimi episodi delle vicende della famiglia Forger. La decisione di prolungare la trasposizione testimonia il vasto successo di pubblico ottenuto dalla serie tratta dal manga di Tatsuya Endo sia in Giappone sia a livello internazionale. Lo riferisce Anime News Network.",
