   "id": "zd9b38770",
   "sez": "dibattito",
   "titolo": "Irlanda, confronto sulle sanzioni ai disoccupati che rifiutano il lavoro",
   "orig": "Fine Gael 'punching down' with unemployment pledge - SF",
   "lead": "In Irlanda si è aperto un confronto politico sulla gestione dei sussidi di disoccupazione e sulle politiche attive per il lavoro. Il leader del partito di governo Fine Gael, Simon Harris, ha proposto di penalizzare i disoccupati di lungo corso che rifiutano di collaborare con i servizi pubblici per il reinserimento professionale, con l'obiettivo dichiarato di incentivare la ricerca attiva di un impiego. Dalle opposizioni, un deputato di Sinn Féin ha contestato duramente l'iniziativa, sostenendo che tale misura rappresenti un attacco ingiusto contro le fasce più deboli e vulnerabili della popolazione anziché un supporto efficace. Lo riferisce RTÉ News.",
   "more": [
    "Nelle economie europee, il dibattito sui regimi di welfare contrappone spesso due modelli di politica del lavoro. Da un lato vi è il principio di condizionalità, che subordina l'erogazione dei sussidi economici alla disponibilità del beneficiario ad accettare offerte o corsi di formazione, mentre dall'altro si privilegiano misure di sostegno sociale prive di sanzioni per proteggere chi incontra barriere strutturali o sociali nell'accesso all'occupazione."
   ],
