   "id": "zc3489ff9",
   "sez": "cultura",
   "titolo": "La formazione giovanile a Durban e la poetica pluralista di Fernando Pessoa",
   "orig": "SOUTH AFRICAN CONNECTION: How an anglophone education in Durban shaped Fernando Pessoa, giant of European literature",
   "lead": "Un saggio critico ripercorre il legame tra la formazione giovanile di Fernando Pessoa e la città sudafricana di Durban, evidenziando come l'istruzione anglofona abbia influenzato la poetica del grande autore europeo. Vissuto tra la fine dell'Ottocento e i primi decenni del Novecento, Pessoa ha sviluppato la convinzione di ricercare la pluralità dell'io nella complessità del mondo, caratteristica che culminò nella celebre creazione dei suoi eteronimi letterari. In un'epoca segnata dal ritorno di nazionalismi e identità chiuse, il pensiero dello scrittore portoghese viene descritto come un antidoto culturale contro le frammentazioni del presente. Lo riferisce Daily Maverick.",
   "more": [
    "Fernando Pessoa è considerato uno dei massimi esponenti del modernismo letterario portoghese e mondiale. La sua particolarità stilistica risiede nell'invenzione di eteronimi, vere e proprie personalità poetiche distinte con biografie, stili e visioni filosofiche autonome, attraverso cui l'autore ha esplorato la frammentarietà dell'identità umana e il rapporto tra individuo, lingua e realtà."
   ],
   "fonti": [
    {
     "n": "Daily Maverick",
     "p": "XX",
     "c": "Città del Capo",
     "u": "https://www.dailymaverick.co.za/article/2026-11-08-how-an-anglophone-education-in-durban-shaped-fernando-pessoa-giant-of-european-literature/",
     "angolo": "",
     "atlas": "South Africa",
     "t": "2026-11-08T11:22+00:00"
    }
   ],
