   "sez": "mondo",
   "titolo": "Estonia, il partito EKRE presenta il programma elettorale per il 2027",
   "orig": "Cheap energy and lower food prices: EKRE announces 2027 election platform",
   "lead": "In Estonia il Partito Popolare Conservatore, noto con la sigla EKRE, ha ufficialmente presentato e approvato la propria piattaforma programmatica in vista delle elezioni politiche previste per il marzo 2027. Durante l'assemblea svoltasi a Tartu, la forza politica di orientamento conservatore ha posto al centro della propria proposta elettorale la riduzione dei prezzi dei generi alimentari e l'offerta di energia a basso costo per famiglie e imprese. Il movimento intende intercettare il malcontento popolare puntando sulla sicurezza economica e sul contenimento dell'inflazione come assi principali della futura campagna elettorale. Lo riferisce ERR News.",
   "more": [
    "L'Estonia, repubblica baltica membro dell'Unione Europea e della Nato, ha registrato negli ultimi anni forti oscillazioni nei prezzi delle materie prime e delle bollette energetiche. Il dibattito politico nazionale vede contrapposte le forze liberali ed europeiste a quelle conservatrici ed euroscettiche, le quali incentrano la contesa su sovranità economica, sicurezza dei confini e tutela del reddito reale dei cittadini."
   ],
