   "id": "z30c205ae",
   "sez": "economia",
   "titolo": "La Tanzania promuove l'orticoltura all'expo HortiLogistica Africa 2026",
   "orig": "Horticulture expo targets global markets",
   "lead": "Ad Arusha si apre la fiera internazionale HortiLogistica Africa 2026, un evento fieristico di tre giorni volto a rafforzare la posizione della Tanzania nei mercati ortofrutticoli globali. La manifestazione, allestita presso gli spazi del TGT grounds, vedrà la partecipazione di oltre tremila delegati provenienti da più di quaranta Paesi e sarà inaugurata ufficialmente dal vicepresidente Deogratius Ndejembi. L'iniziativa mira a creare opportunità commerciali, favorire partnership nella catena del valore agricolo e attirare investitori esteri nelle filiere di conservazione, trasporto ed esportazione dei prodotti orticoli coltivati nel continente africano. Lo riferisce Daily News (Tanzania).",
   "more": [
    "L'orticoltura rappresenta uno dei settori più dinamici dell'agricoltura commerciale nell'Africa orientale, con un forte potenziale di esportazione verso l'Europa e il Medio Oriente. Lo sviluppo della logistica a catena del freddo e delle infrastrutture di smistamento rapido costituisce un passaggio indispensabile per ridurre le perdite post-raccolto e garantire standard qualitativi conformi ai mercati internazionali."
   ],
