   "id": "z5d1852f7",
   "sez": "mondo",
   "titolo": "Riparazioni per la schiavitù e disuguaglianze strutturali: il confronto aperto",
   "orig": "Slavery debt is far from settled",
   "lead": "Il dibattito sui risarcimenti economici per la tratta transatlantica degli schiavi resta pienamente aperto e continua a contestare le disuguaglianze strutturali ereditate dall'epoca degli imperi europei. Un'analisi approfondita evidenzia come le conseguenze economiche e sociali dello schiavismo abbiano plasmato disparità secolari tra Nord e Sud del mondo, smentendo le ricostruzioni politiche che tentano di archiviare le responsabilità storiche del colonialismo. La richiesta di compensazioni e riparazioni formali viene pertanto riproposta come una questione centrale di giustizia globale e di riequilibrio delle ricchezze accumulate a danno delle popolazioni sottomesse. Lo riferisce Mail & Guardian.",
   "more": [
    "La questione delle riparazioni storiche per lo schiavismo e il dominio coloniale è sostenuta da vari governi africani e caraibici all'interno delle sedi internazionali. Il dibattito verte sia sul riconoscimento ufficiale dei crimini commessi durante la tratta, sia sulla restituzione di beni culturali e sull'adozione di misure di sostegno economico e cancellazione del debito per gli Stati post-coloniali."
   ],
