   "id": "z16708d57",
   "sez": "economia",
   "titolo": "Kenya, ultimatum di trenta giorni all'università TUK per i debiti pensionistici",
   "orig": "Cash-strapped TUK given 30 days to pay Sh6.4bn pension debt",
   "lead": "In Kenya la Technical University of Kenya ha ricevuto un ultimatum di trenta giorni per saldare un debito pensionistico di 6,4 miliardi di scellini accumulato nei confronti del fondo previdenziale dei dipendenti. L'ateneo della capitale versa in una profonda crisi finanziaria che ha finito per bloccare e mettere a rischio i risparmi destinati alla quiescenza del personale accademico e amministrativo. Le autorità di vigilanza hanno fissato una scadenza perentoria per avviare il rientro dei versamenti arretrati, mentre i sindacati dei lavoratori denunciano la gravità della situazione e chiedono interventi governativi per risanare i conti dell'istituzione. Lo riferisce Daily Nation.",
   "more": [
    "Diverse università pubbliche in Kenya affrontano da anni pesanti deficit di bilancio dovuti alla riduzione dei trasferimenti statali e al calo delle iscrizioni a pagamento. L'incapacità di versare regolarmente i contributi previdenziali e assicurativi tratti dalle buste paga dei lavoratori ha provocato ripetuti interventi della magistratura e degli organi regolatori a salvaguardia dei diritti pensionistici dei dipendenti."
   ],
