   "sez": "economia",
   "titolo": "Libia, gestione efficiente e fiducia per valorizzare i ricavi dello spazio aereo",
   "orig": "Maximising economic return of Libya’s airspace: Efficient aviation management and return of trust are key",
   "lead": "Al Forum internazionale dell'aviazione organizzato in Libia è stato presentato uno studio strategico incentrato sulla massimizzazione dei ritorni economici derivanti dalla gestione dello spazio aereo nazionale. Secondo il documento illustrato durante la conferenza, il Paese può trarre ingenti entrate finanziarie dai diritti di sorvolo e dal traffico commerciale soltanto attraverso un'amministrazione moderna ed efficiente dei servizi di navigazione e il pieno ripristino della fiducia da parte delle compagnie aeree internazionali. Gli esperti del settore sottolineano che la sicurezza dei cieli e gli investimenti nelle infrastrutture radar restano precondizioni indispensabili per sbloccare queste risorse. Lo riferisce Libya Herald.",
   "more": [
    "I diritti di sorvolo aereo costituiscono una voce di entrata significativa per gli Stati che occupano posizioni geografiche nodali lungo le rotte commerciali intercontinentali. In Libia, anni di instabilità politica e scontri armati hanno comportato la chiusura o la restrizione di ampi settori dello spazio aereo da parte degli enti internazionali per la sicurezza, allontanando i vettori aerei stranieri."
   ],
