   "sez": "economia",
   "titolo": "Libia, confermato a Sebha l'International Fezzan Economic Forum a fine novembre",
   "orig": "International Fezzan Economic Forum press conference confirms event to be held in Sebha from 24 to 26 November",
   "lead": "A Sebha, capoluogo della regione meridionale del Fezzan, gli organizzatori dell'International Fezzan Economic Forum hanno tenuto una conferenza stampa ufficiale per confermare lo svolgimento della manifestazione dal 24 al 26 novembre prossimi. L'evento intende attirare l'attenzione di investitori, istituzioni e aziende sulle potenzialità economiche e commerciali della Libia meridionale, storicamente emarginata rispetto ai centri costieri. Nel corso della presentazione i promotori hanno ribadito l'obiettivo di favorire progetti di sviluppo infrastrutturale, partnership pubblico-private e nuove opportunità di occupazione per la popolazione locale attraverso il rilancio produttivo dell'area sahariana. Lo riferisce Libya Herald.",
   "more": [
    "Il Fezzan è la vasta provincia desertica della Libia sud-occidentale, ricca di risorse petrolifere e idriche sotterranee ma afflitta da carenze nei servizi e collegamenti viari. Lo sviluppo economico di quest'area periferica è ritenuto fondamentale non solo per l'economia nazionale libica, ma anche per stabilizzare le frontiere meridionali e contrastare i traffici illeciti transfrontalieri nel Sahel."
   ],
