   "sez": "economia",
   "titolo": "Banca Centrale della Libia: completato il passaggio di consegne al vertice",
   "orig": "Central Bank of Libya completes official handover procedures for the outgoing and new Governor",
   "lead": "La Banca Centrale della Libia ha comunicato di aver completato le procedure formali di passaggio di consegne tra il governatore uscente e il nuovo vertice dell'istituto di emissione monetaria. L'avvicendamento ufficiale dell'ufficio governativo segna un passaggio istituzionale rilevante per la stabilità finanziaria del Paese nordafricano, dopo mesi di aspre contese politiche sulla gestione dei conti pubblici e sul controllo delle entrate petrolifere. Con il completamento della transizione amministrativa, la banca punta a ristabilire la regolarità delle operazioni creditizie, a rafforzare la moneta nazionale e a garantire la continuità dei pagamenti statali. Lo riferisce Libya Herald.",
   "more": [
    "La Banca Centrale della Libia riveste un ruolo strategico unico nel Paese, poiché gestisce direttamente i proventi delle esportazioni di idrocarburi e finanzia la spesa pubblica di entrambe le fazioni politiche rivali. Il controllo della presidenza della banca è stato a lungo al centro di contese che hanno rischiato di bloccare l'economia nazionale e interrompere la produzione energetica libica."
   ],
