   "id": "z19ce5cda",
   "sez": "economia",
   "titolo": "Presidenza della BCE: sfida a due tra Olanda e Spagna per la successione",
   "orig": "Dutchman and Spaniard in two-horse race for ECB presidency",
   "lead": "La corsa per la futura presidenza della Banca Centrale Europea si profila come una sfida a due tra un candidato olandese e uno spagnolo, dopo che alla scadenza di venerdì non sono state formalizzate altre candidature ufficiali. Nonostante la ristretta rosa di pretendenti emersa alla chiusura dei termini, gli analisti non escludono che possa ancora spuntare a sorpresa un nome esterno, come avvenne nel 2019 quando fu designata Christine Lagarde. La scelta della guida dell'istituto di Francoforte influenzerà l'indirizzo della politica monetaria dell'Eurozona, le decisioni sui tassi di interesse e le strategie di stabilità finanziaria comunitaria. Lo riferisce The Japan Times.",
   "more": [
    "La presidenza della Banca Centrale Europea è una delle cariche più influenti dell'Unione Europea, nominata dal Consiglio europeo a maggioranza qualificata su raccomandazione dell'Eurogruppo. Il mandato, non rinnovabile, dura otto anni e richiede un profilo di riconosciuta competenza monetaria e bancaria, capace di bilanciare le sensibilità economiche dei Paesi del Nord e del Sud del continente."
   ],
