   "id": "zb3bbe5e1",
   "sez": "economia",
   "titolo": "La cinese Huaxin acquisisce CSN Cimentos ed entra nel mercato del Brasile",
   "orig": "China to enter Brazil’s cement market as Huaxin agrees to buy CSN Cimentos",
   "lead": "Il colosso cinese dei materiali edili Huaxin Building Materials Group ha firmato un accordo per acquisire il 99,99 per cento delle quote di CSN Cimentos, il secondo produttore di cemento del Brasile, per un controvalore di 1,64 miliardi di dollari. L'operazione societaria segna lo storico ingresso della Cina nel mercato brasiliano del cemento attraverso l'acquisizione concordata con la società sudamericana. Il gruppo industriale con sede nella provincia dell'Hubei, quotato sia a Shanghai sia a Hong Kong, espande così la propria presenza internazionale in America Latina, rafforzando gli investimenti cinesi nelle infrastrutture e nelle costruzioni oltreoceano. Lo riferisce South China Morning Post – Economia.",
   "more": [
    "L'accordo tra Huaxin e CSN Cimentos si inserisce nella crescente strategia di internazionalizzazione delle imprese manifatturiere cinesi, intenzionate a espandersi nei mercati emergenti dell'America Latina. Il Brasile, principale economia della regione, offre un mercato interno in crescita grazie a piani di riqualificazione infrastrutturale e progetti residenziali, rendendo il settore dei materiali da costruzione particolarmente attrattivo per i grandi gruppi esteri."
   ],
