   "id": "zce03d67d",
   "sez": "economia",
   "titolo": "Hong Kong, HSBC investe sulle filiali fisiche tra caffè e servizi esclusivi",
   "orig": "HSBC bets HK$4 million a month on flagship branch to keep physical outlets relevant",
   "lead": "A Hong Kong il colosso bancario HSBC ha deciso di investire circa quattro milioni di dollari di Hong Kong al mese per mantenere operativa la sua nuova filiale di punta a Causeway Bay. La sede, distribuita su cinque piani e oltre tremila metri quadrati all'interno del Capitol Centre, punta su servizi insoliti come bar, macaron e massaggi con oli essenziali per attirare i clienti nei locali fisici. In un momento in cui le banche tradizionali ripensano la propria rete territoriale a fronte della rapida diffusione dei servizi digitali, l'istituto scommette sull'accoglienza per preservare l'attrattiva degli sportelli. Lo riferisce South China Morning Post – Economia.",
   "more": [
    "La progressiva transizione verso i servizi di online banking ha spinto molti istituti di credito globali a ridurre drasticamente il numero di filiali sul territorio per contenere i costi di gestione. Alcune grandi banche hanno scelto tuttavia di trasformare le sedi rimanenti in centri di consulenza e accoglienza ad alto valore aggiunto, puntando su esperienze personalizzate per fidelizzare la clientela facoltosa."
   ],
