   "id": "zb83bc303",
   "sez": "cucina",
   "titolo": "Uno chef samoano porta i sapori dell'isola nell'alta cucina della Nuova Zelanda",
   "orig": "Samoan Chef Brings Flavors of Home to New Zealand’s Fine-Dining Scene",
   "lead": "Lo chef samoano Henry Onesemo ha portato le tradizioni culinarie della sua isola d'origine nel panorama dell'alta ristorazione in Nuova Zelanda, proponendo i sapori del Pacifico meridionale nel suo ristorante premiato con la stella Michelin. Cresciuto con la cultura gastronomica locale al centro della propria vita familiare, lo chef unisce le ricette tradizionali alle tecniche contemporanee di cucina, contribuendo a far conoscere la cultura gastronomica di Samoa e ad arricchire l'offerta culinaria internazionale del Paese che lo ospita.",
   "more": [
    "La cucina tradizionale delle isole Samoa si basa su ingredienti locali come pesce fresco, frutti dell'albero del pane, taro e latte di cocco. L'integrazione di questi elementi nella ristorazione di alto livello riflette la crescente valorizzazione delle tradizioni gastronomiche indigene e del Pacifico nella scena culinaria globale contemporanea."
   ],
