   "id": "z47660944",
   "sez": "mondo",
   "titolo": "Esplosioni in Iran e navi colpite nelle vicinanze dello stretto di Hormuz",
   "orig": "Iran suggests blasts are not US attacks as both sides report ships hit",
   "lead": "I media statali dell'Iran hanno riferito che le esplosioni avvertite nel sud del Paese, tra cui l'isola di Qeshm nello stretto di Hormuz, sono riconducibili ad attività militari interne e non ad attacchi statunitensi. Allo stesso tempo, sia le autorità iraniane sia fonti americane hanno segnalato che alcune imbarcazioni mercantili sono state colpite nelle acque dello stretto o nelle vicinanze. Gli episodi si inseriscono in un contesto di forte tensione nella regione mediorientale, segnato da timori di ripercussioni sulla navigazione commerciale.",
   "more": [
    "Lo stretto di Hormuz è uno dei punti di transito marittimo più strategici al mondo per il commercio globale di petrolio e gas naturale. Situato tra il Golfo Persico e il Golfo di Oman, qualsiasi instabilità o minaccia alla sicurezza della navigazione nell'area provoca immediate reazioni sui mercati energetici internazionali."
   ],
