   "id": "z05e64929",
   "sez": "mondo",
   "titolo": "Sánchez propone di blindare pensioni e aborto nella Costituzione spagnola",
   "orig": "Sánchez reenfoca la campaña del PSOE en la gestión y asegura que blindará las pensiones en la Constitución",
   "lead": "Il presidente del governo spagnolo Pedro Sánchez ha rilanciato la campagna elettorale del Partito Socialista Operaio Spagnolo concentrandosi sui risultati di gestione e proponendo una riforma della Costituzione per blindare le pensioni e il diritto all'aborto. Sánchez ha criticato le posizioni del leader dell'opposizione Alberto Núñez Feijóo e il possibile accordo di governo con la formazione di destra Vox, presentando la propria piattaforma sociale come un baluardo a tutela dei diritti fondamentali e dei lavoratori di fronte alle spinte conservatrici.",
   "more": [
    "La Costituzione spagnola del 1978 stabilisce i principi fondamentali dello Stato sociale e democratico di diritto. L'inserimento del diritto alle pensioni e dell'interruzione volontaria di gravidanza nel testo costituzionale richiederebbe una maggioranza qualificata in Parlamento, un passaggio istituzionale mirato a proteggere tali diritti da eventuali modifiche da parte di future maggioranze politiche."
   ],
