   "id": "z3e5effcf",
   "sez": "cultura",
   "titolo": "Il tavolo del Trattato di pace di Tartu in mostra al Ministero degli Esteri estone",
   "orig": "Tartu Peace Treaty talks table on display at Ministry of Foreign Affairs",
   "lead": "Il tavolo delle trattative storiche utilizzato durante i colloqui per il Trattato di pace di Tartu tra l'Estonia e l'Unione Sovietica tra il 1919 e il 1920 è stato temporaneamente esposto presso la sede del Ministero degli Affari Esteri a Tallinn. L'iniziativa offre al pubblico la possibilità di osservare un reperto simbolo dell'indipendenza estone, legato al momento diplomatico fondamentale che sancì il riconoscimento della sovranità del Paese baltico al termine della guerra di liberazione.",
   "more": [
    "Il Trattato di pace di Tartu, firmato il 2 febbraio 1920, pose fine alla guerra d'indipendenza estone e rappresentò il primo riconoscimento formale dello Stato estone da parte della Russia sovietica. La conservazione e la mostra di cimeli storici legati a quell'accordo costituiscono un elemento centrale per la memoria d'identità nazionale del Paese."
   ],
