   "id": "z1542cee0",
   "sez": "sport",
   "titolo": "Sydney Swans e Hawthorn Hawks avanzano nelle finali del campionato AFLW",
   "orig": "Swans, Hawks prevail in AFLW elimination finals",
   "lead": "Nelle finali a eliminazione diretta del campionato di football australiano femminile AFLW, le Sydney Swans hanno superato le Western Bulldogs in una partita caratterizzata da pioggia e forte vento, assicurandosi il passaggio del turno. Nella seconda sfida, le Hawthorn Hawks hanno sconfitto le Gold Coast Suns, ottenendo la prima storica vittoria nella fase finale della competizione. I risultati determinano la composizione del quadro dei quarti di finale per la conquista del titolo nazionale della stagione.",
   "more": [
    "L'AFL Women's è la principale lega professionistica di football australiano femminile, fondata nel 2017 per promuovere la disciplina a livello nazionale. La competizione comprende una fase regolare seguita da playoff a eliminazione diretta che decretano la squadra campione d'Australia alla fine di ogni stagione agonistica."
   ],
