   "id": "za2075801",
   "sez": "prima",
   "titolo": "Almeno 21 morti nel naufragio di una piroga di migranti al largo del Senegal",
   "orig": "Au large du Sénégal, au moins 21 personnes sont mortes dans le naufrage d'une pirogue de migrants",
   "lead": "Almeno ventuno persone sono morte nel naufragio di una piroga che trasportava migranti al largo delle coste di Kébémer, nel nord-ovest del Senegal. Lo hanno confermato le autorità locali e il ministero dell'Interno senegalese, spiegando che finora è stato tratto in salvo un solo superstite. I soccorritori e le forze di sicurezza proseguono le operazioni di ricerca in mare nel tentativo di individuare eventuali altri sopravvissuti, mentre le istituzioni tentano di ricostruire l'esatta dinamica della tragedia marittima.",
   "more": [
    "La rotta migratoria dell'Africa occidentale verso le Isole Canarie è una delle più pericolose al mondo per via delle fortissime correnti oceaniche e dell'impiego di imbarcazioni precarie. Molti migranti tentano la traversata partendo dalle coste senegalesi o mauritane nella speranza di raggiungere il territorio europeo e trovare migliori condizioni economiche."
   ],
