   "id": "zb825be09",
   "sez": "sport",
   "titolo": "Stéphanie Nsimba Manzanza conquista la prima medaglia olimpica della RDC a Dakar 2026",
   "orig": "JOJ Dakar 2026 : la lutteuse Stéphanie Nsimba Manzanza offre à la RDC sa première médaille olympique",
   "lead": "La lottatrice Stéphanie Nsimba Manzanza ha conquistato la prima medaglia olimpica nella storia dello sport della Repubblica Democratica del Congo ai Giochi olimpici della gioventù 2026 di Dakar. L'atleta congolese ha ottenuto il podio nella disciplina della lotta, segnando un traguardo storico per la delegazione del suo Paese durante la manifestazione internazionale svoltasi in Senegal, festeggiato con grande entusiasmo dai media e dalle autorità sportive nazionali.",
   "more": [
    "I Giochi olimpici della gioventù sono un evento multisportivo internazionale promosso dal Comitato Olimpico Internazionale per atleti di età compresa tra i 14 e i 18 anni. Oltre alle competizioni sportive, la manifestazione include programmi culturali ed educativi pensati per promuovere i valori olimpici tra i giovani di tutto il mondo."
   ],
