   "id": "z74cc2d6d",
   "sez": "economia",
   "titolo": "Baowu Resources presenta a Shanghai il rapporto sul progetto minerario di Simandou",
   "orig": "Guinée : Baowu Resources expose les avantages du projet Simandou",
   "lead": "L'azienda mineraria cinese Baowu Resources ha presentato a Shanghai un rapporto sulla sostenibilità ambientale e sociale dedicato al progetto di estrazione del ferro di Simandou, in Guinea. Alla presentazione, tenutasi durante la novena Mostra internazionale dell'importazione della Cina alla presenza del ministro delle Miniere guineano, la società ha illustrato gli impatti economici del giacimento. Il progetto è considerato cruciale per lo sviluppo delle infrastrutture e per l'attrazione di investimenti internazionali nel Paese africano.",
   "more": [
    "Il giacimento di Simandou, situato nel sud-est della Guinea, possiede una delle più grandi riserve incontaminate di minerale di ferro ad alta percentuale al mondo. La sua estrazione richiede massicci investimenti in infrastrutture, tra cui ferrovie e porti, fondamentali per l'esportazione del minerale verso i mercati internazionali."
   ],
