   "sez": "mondo",
   "titolo": "Tre analisti tracciano il bilancio del primo anno del governo in Bolivia",
   "orig": "Lo bueno, lo malo y lo pendiente: tres analistas ponen el primer año del gobierno bajo la lupa",
   "lead": "In Bolivia tre analisti politici hanno tracciato un bilancio del primo anno del governo nazionale, evidenziando il taglio dei sussidi statali come uno degli interventi positivi principali per il consolidamento economico. Allo stesso tempo, gli esperti hanno espresso critiche per le improvvisazioni nella gestione amministrativa e per l'impatto delle recenti decisioni politiche sul Paese. Il dibattito riflette le divisioni dell'opinione pubblica sulle riforme in corso e sulla stabilità istituzionale boliviana.",
   "more": [
    "La rimozione dei sussidi sui carburanti e sui beni di prima necessità rappresenta una misura di politica economica complessa spesso adottata per ridurre il deficit pubblico. Tuttavia, tali provvedimenti comportano un impatto immediato sul costo della vita per i cittadini, innescando accesi dibattiti tra sostenitori del rigore fiscale e oppositori sociali."
   ],
