   "sez": "mondo",
   "titolo": "Scontri e devastazioni al liceo dei Martiri a Bangui dopo una protesta di studenti",
   "orig": "Lycée des Martyrs : comment une colère scolaire a-t-elle dégénéré en violences ?",
   "lead": "Una manifestazione di studenti presso il liceo dei Martiri a Bangui, nella Repubblica Centrafricana, si è trasformata in scontri e atti di violenza diffusi. Nel corso delle proteste alcuni edifici ufficiali sono stati saccheggiati e danneggiati dai manifestanti. Per ripristinare l'ordine pubblico, le forze di polizia sono intervenute facendo uso di gas lacrimogeni per disperdere la folla. Le autorità locali hanno avviato accertamenti per chiarire i motivi che hanno scatenato la rabbia degli studenti.",
   "more": [
    "Le proteste studentesche nella Repubblica Centrafricana nascono frequentemente da rivendicazioni legate alle scarse risorse scolastiche, al ritardo nel pagamento delle borse di studio o a tensioni con la gestione amministrativa degli istituti. La fragilità del sistema educativo rende spesso difficili le mediazioni tra gli studenti e i responsabili delle istituzioni formative."
   ],
