   "titolo": "Scontro tragico in volo tra due paracadutisti durante un tentativo di record in California",
   "orig": "Tragedia en California, Estados Unidos: dos paracaidistas murieron tras chocar en pleno vuelo durante un evento que buscaba romper un récord mundial",
   "lead": "I due atleti si stavano preparando alla fase di atterraggio quando le loro imbracature e paracadute si sono enredati a causa di una collisione avvenuta a circa quarantasei metri dal suolo. Nonostante i soccorsi immediati giunti sul luogo dell'incidente, i medici non hanno potuto salvare la vita ai due sportivi.",
   "more": [
    "I lanci in paracadutismo di gruppo mirati a stabilire record mondiali richiedono la coordinazione simultanea di decine di paracadutisti in aria. L'alta densità di atleti in uno spazio aereo ristretto aumenta il rischio di collisioni durante le fasi critiche di apertura dei paracadute e di avvicinamento al terreno di atterraggio."
   ],
