   "id": "z0ef6cc36",
   "sez": "sport",
   "titolo": "Infortunio al tendine per il portiere del Bayern Monaco Manuel Neuer",
   "orig": "Bayern keeper Neuer suffers partial foot tendon tear",
   "lead": "Il portiere del Bayern Monaco Manuel Neuer ha riportato la lesione parziale di un tendine del piede, un infortunio che lo costringerà a rimanere lontano dai campi di gioco per diverse settimane. La notizia della sua assenza è stata confermata dalla società tedesca e ha suscitato preoccupazione nello staff tecnico guidato da Vincent Kompany. Il club bavarese dovrà valutare le opzioni a disposizione in rosa per sostituire l'esperto capitano nelle prossime sfide di campionato e delle coppe europee.",
   "more": [
    "Manuel Neuer è considerato uno dei portieri più vincenti della storia recente del calcio mondiale, capitano del Bayern Monaco e campione del mondo nel 2014 con la Germania. Gli infortuni ai tendini o ai piedi nei calciatori di alto livello richiedono trattamenti cautelativi per evitare ricadute durante l'attività agonistica."
   ],
