   "id": "ze8086928",
   "sez": "prima",
   "titolo": "Il ministro Piantedosi convoca il Comitato per la sicurezza dopo gli attacchi cyber",
   "orig": "Attacchi informatici, riunito Comitato Sicurezza",
   "lead": "Il ministro dell'Interno Matteo Piantedosi ha convocato per martedì 10 novembre al Viminale una riunione del Comitato nazionale per l'ordine e la sicurezza pubblica con i vertici delle forze dell'ordine. Al centro dell'incontro vi sarà l'esame approfondito delle minacce per la sicurezza pubblica legate ai recenti attacchi informatici che hanno preso di mira infrastrutture e istituzioni italiane. Anche il ministro degli Esteri Antonio Tajani anticiperà la posizione dell'Italia sul tema della protezione digitale al vertice del G7.",
   "more": [
    "La sicurezza informatica delle infrastrutture pubbliche è diventata una priorità strategica per la difesa nazionale. Il Comitato nazionale per l'ordine e la sicurezza pubblica è l'organo consultivo presieduto dal ministro dell'Interno che analizza i rischi per il Paese e pianifica gli interventi coordinati tra forze di polizia, intelligence e agenzie di cybersicurezza."
   ],
